-- ===== connectors-local.sql =====
-- LOCAL PRO ONLY. Round 6B (2026-11-13): owner connectors (Houzz parity rows 10 and 72) and the OAuth vault
-- shared with QuickBooks (row 56).
-- * OAuth 2.0 authorization code + PKCE (S256) + single-use state: only the SHA-256 of the state is stored,
--   with the PKCE verifier ENCRYPTED; a state expires after 10 minutes and can be consumed once.
-- * Tokens are stored ONLY as AES-256-GCM envelopes produced by the server («v1.<key>.<iv>.<tag>.<data>»);
--   the CHECK rejects anything else, so a plaintext token can never be stored. Revoking wipes them.
-- * Email: every send needs the owner's explicit confirmation (confirmed=true from the UI dialog). In mock
--   mode the message is only kept in the outbox (status «simulated»): the CHECK forbids any other status.
-- * Calendar: two-way sync links (appointment = scheduled job of the agenda, task = open task with a date),
--   conflicts kept with both versions; events created in the calendar are imported as busy time.
--   pro_mock_calendar_events is the local stand-in of the remote calendar (mock mode only).
-- Tables: RLS on, service_role only; functions security invoker, executable by service_role only.
begin;

create or replace function public.pro_oauth_box_ok(p_box text) returns boolean
language sql immutable security invoker set search_path=public,pg_temp as $$
 select p_box is null or length(p_box)<=16500 and p_box ~ '^v1\.(mock|env)\.[A-Za-z0-9_-]{16}\.[A-Za-z0-9_-]{22}\.[A-Za-z0-9_-]{8,}$' $$;

create table if not exists public.pro_oauth_states(
 id uuid primary key,owner_id uuid not null references public.profiles(id) on delete cascade,
 provider text not null check(provider in('google','microsoft','quickbooks')),
 mode text not null check(mode in('mock','sandbox','production')),
 state_hash text not null unique check(state_hash~'^[a-f0-9]{64}$'),
 verifier_box text not null check(public.pro_oauth_box_ok(verifier_box)),
 locale text not null check(locale in('es','en')),return_view text not null check(return_view in('conectores','contabilidad','integraciones')),
 created_at timestamptz not null default now(),expires_at timestamptz not null,used_at timestamptz
);
create index if not exists pro_oauth_states_owner on public.pro_oauth_states(owner_id,created_at desc);
create table if not exists public.pro_oauth_connections(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 provider text not null check(provider in('google','microsoft','quickbooks')),
 mode text not null check(mode in('mock','sandbox','production')),
 status text not null check(status in('connected','revoked')),
 account_email text check(account_email is null or length(account_email)<=254),
 scopes text[] not null default '{}' check(cardinality(scopes)<=20),
 access_box text check(public.pro_oauth_box_ok(access_box)),
 refresh_box text check(public.pro_oauth_box_ok(refresh_box)),
 access_expires_at timestamptz,
 realm_id text check(realm_id is null or realm_id~'^[0-9]{1,30}$'),
 connected_at timestamptz,revoked_at timestamptz,
 revision integer not null default 1 check(revision>0),updated_at timestamptz not null default now(),
 primary key(owner_id,provider),
 check(status<>'connected' or access_box is not null and connected_at is not null),
 check(status<>'revoked' or access_box is null and refresh_box is null and revoked_at is not null)
);
create table if not exists public.pro_oauth_history(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null default gen_random_uuid(),
 provider text not null,mode text not null,action text not null check(action in('connect','refresh','revoke','denied','failed')),
 detail jsonb not null default '{}' check(octet_length(detail::text)<=2048 and public.pro_integration_config_safe(detail)),
 at timestamptz not null default clock_timestamp(),primary key(owner_id,id)
);
create table if not exists public.pro_connector_actions(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 action_id uuid not null,scope text not null check(length(scope) between 1 and 40),input jsonb not null,result jsonb not null,created_at timestamptz not null default now(),primary key(owner_id,action_id)
);

create table if not exists public.pro_email_outbox(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,
 provider text not null check(provider in('google','microsoft')),mode text not null check(mode in('mock','sandbox','production')),
 from_email text not null check(length(from_email)<=254),
 to_emails text[] not null check(cardinality(to_emails) between 1 and 10),
 subject text not null check(length(btrim(subject)) between 1 and 200),
 body text not null check(length(btrim(body)) between 1 and 20000),
 work_id text,
 attachments jsonb not null default '[]' check(jsonb_typeof(attachments)='array' and jsonb_array_length(attachments)<=10 and public.pro_integration_config_safe(attachments)),
 status text not null check(status in('simulated','queued','sent','failed')),
 confirmed_at timestamptz not null,
 provider_message_id text check(provider_message_id is null or length(provider_message_id)<=200),
 error text check(error is null or length(error)<=300),
 created_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,id),foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete set null(work_id),
 -- Mock never sends: its only possible status is «simulated», and «simulated» exists only in mock.
 check((mode='mock')=(status='simulated'))
);
create index if not exists pro_email_outbox_recent on public.pro_email_outbox(owner_id,created_at desc);

create table if not exists public.pro_calendar_links(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 provider text not null check(provider in('google','microsoft')),mode text not null check(mode in('mock','sandbox','production')),
 local_kind text not null check(local_kind in('appointment','task')),local_id text not null check(length(local_id) between 1 and 160),
 remote_id text not null check(length(remote_id) between 1 and 200),
 local_fingerprint text not null check(local_fingerprint~'^[a-f0-9]{32}$'),
 remote_etag text not null check(length(remote_etag) between 1 and 200),
 status text not null default 'synced' check(status in('synced','conflict','removed')),
 conflict jsonb check(conflict is null or jsonb_typeof(conflict)='object' and octet_length(conflict::text)<=4096),
 title text not null check(length(title) between 1 and 300),
 synced_at timestamptz not null default now(),revision integer not null default 1 check(revision>0),
 primary key(owner_id,provider,local_kind,local_id),
 check((status='conflict')=(conflict is not null))
);
create table if not exists public.pro_calendar_external(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 provider text not null check(provider in('google','microsoft')),remote_id text not null check(length(remote_id) between 1 and 200),
 title text not null check(length(title) between 1 and 300),starts_at timestamptz not null,ends_at timestamptz not null,all_day boolean not null default false,
 seen_at timestamptz not null default now(),primary key(owner_id,provider,remote_id),check(ends_at>=starts_at)
);
-- Local stand-in of the owner's remote calendar (mock mode only; never used by real adapters).
create table if not exists public.pro_mock_calendar_events(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 provider text not null check(provider in('google','microsoft')),id text not null check(length(id) between 1 and 200),
 title text not null check(length(title) between 1 and 300),starts_at timestamptz not null,ends_at timestamptz not null,all_day boolean not null default false,
 etag integer not null default 1 check(etag>0),origin text not null check(origin in('ccr','external')),deleted boolean not null default false,
 updated_at timestamptz not null default now(),primary key(owner_id,provider,id),check(ends_at>=starts_at)
);

create or replace function public.pro_connectors_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if tg_op='UPDATE' then raise exception 'Connector history and receipts are immutable' using errcode='23514';end if;
 if exists(select 1 from public.profiles where id=old.owner_id) then raise exception 'Connector history and receipts are immutable' using errcode='23514';end if;
 return old;
end $$;
do $$declare n text;begin foreach n in array array['pro_oauth_history','pro_connector_actions'] loop
 execute format('drop trigger if exists pro_connectors_immutable on public.%I',n);
 execute format('create trigger pro_connectors_immutable before update or delete on public.%I for each row execute function public.pro_connectors_immutable()',n);
end loop;end $$;
-- Outbox rows are records of what the owner confirmed: content never changes; only queued → sent|failed.
create or replace function public.pro_email_outbox_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if tg_op='DELETE' then if exists(select 1 from public.profiles where id=old.owner_id) then raise exception 'Outbox is kept' using errcode='23514';end if;return old;end if;
 if new.id<>old.id or new.owner_id<>old.owner_id or new.provider<>old.provider or new.mode<>old.mode or new.to_emails<>old.to_emails or new.subject<>old.subject or new.body<>old.body
  or new.attachments<>old.attachments or new.confirmed_at<>old.confirmed_at or new.from_email<>old.from_email or new.created_at<>old.created_at then raise exception 'Outbox content is immutable' using errcode='23514';end if;
 if new.status<>old.status and not(old.status='queued' and new.status in('sent','failed')) then raise exception 'Invalid outbox transition' using errcode='23514';end if;
 if new.status=old.status and new is distinct from old and old.status<>'queued' then raise exception 'Outbox row is final' using errcode='23514';end if;
 return new;
end $$;
drop trigger if exists pro_email_outbox_guard on public.pro_email_outbox;
create trigger pro_email_outbox_guard before update or delete on public.pro_email_outbox for each row execute function public.pro_email_outbox_guard();

create or replace function public.pro_connector_receipt(p_actor uuid,p_input jsonb,p_scope text) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;receipt public.pro_connector_actions;
begin
 begin aid:=(p_input->>'actionId')::uuid;exception when others then raise exception 'Invalid action id' using errcode='22023';end;
 if aid is null then raise exception 'Invalid action id' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-connector:'||p_actor::text,0));
 select * into receipt from public.pro_connector_actions where owner_id=p_actor and action_id=aid;
 if found then if receipt.input<>p_input or receipt.scope<>p_scope then raise exception 'Action identity reused with different payload' using errcode='22023';end if;return receipt.result;end if;
 return null;
end $$;

-- OAuth: begin stores the hashed state; consume returns it once (owner checked by the server against the session).
create or replace function public.pro_oauth_begin(p_actor uuid,p_input jsonb) returns uuid
language plpgsql security invoker set search_path=public,pg_temp as $$
declare sid uuid:=gen_random_uuid();
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 delete from public.pro_oauth_states where owner_id=p_actor and (expires_at<now() or used_at is not null);
 if (select count(*) from public.pro_oauth_states where owner_id=p_actor)>=10 then raise exception 'Too many pending connections' using errcode='54000';end if;
 insert into public.pro_oauth_states(id,owner_id,provider,mode,state_hash,verifier_box,locale,return_view,expires_at)
 values(sid,p_actor,p_input->>'provider',p_input->>'mode',p_input->>'stateHash',p_input->>'verifierBox',coalesce(p_input->>'locale','es'),coalesce(p_input->>'view','conectores'),now()+interval '10 minutes');
 return sid;
exception when check_violation or not_null_violation or unique_violation then raise exception 'Invalid OAuth state' using errcode='22023';
end $$;
create or replace function public.pro_oauth_consume(p_state_hash text) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare s public.pro_oauth_states;
begin
 select * into s from public.pro_oauth_states where state_hash=p_state_hash for update;
 if not found or s.used_at is not null or s.expires_at<now() then raise exception 'OAuth state invalid, used or expired' using errcode='22023',hint='pro_oauth_state';end if;
 update public.pro_oauth_states set used_at=now() where id=s.id;
 return jsonb_build_object('ownerId',s.owner_id,'provider',s.provider,'mode',s.mode,'verifierBox',s.verifier_box,'locale',s.locale,'view',s.return_view);
end $$;
create or replace function public.pro_oauth_store(p_actor uuid,p_provider text,p_mode text,p_payload jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare c public.pro_oauth_connections;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 if not public.pro_oauth_box_ok(p_payload->>'accessBox') or p_payload->>'accessBox' is null or not public.pro_oauth_box_ok(p_payload->>'refreshBox') then raise exception 'Tokens must be encrypted' using errcode='22023',hint='pro_oauth_plaintext';end if;
 insert into public.pro_oauth_connections(owner_id,provider,mode,status,account_email,scopes,access_box,refresh_box,access_expires_at,realm_id,connected_at,revoked_at)
 values(p_actor,p_provider,p_mode,'connected',left(p_payload->>'accountEmail',254),coalesce((select array_agg(x) from jsonb_array_elements_text(p_payload->'scopes') x),'{}'),
  p_payload->>'accessBox',p_payload->>'refreshBox',(p_payload->>'expiresAt')::timestamptz,p_payload->>'realmId',now(),null)
 on conflict(owner_id,provider) do update set mode=excluded.mode,status='connected',account_email=excluded.account_email,scopes=excluded.scopes,access_box=excluded.access_box,
  refresh_box=excluded.refresh_box,access_expires_at=excluded.access_expires_at,realm_id=excluded.realm_id,connected_at=now(),revoked_at=null,
  revision=pro_oauth_connections.revision+1,updated_at=now()
 returning * into c;
 insert into public.pro_oauth_history(owner_id,provider,mode,action,detail) values(p_actor,p_provider,p_mode,coalesce(nullif(p_payload->>'historyAction',''),'connect'),jsonb_build_object('account',c.account_email,'scopes',to_jsonb(c.scopes)));
 return jsonb_build_object('provider',c.provider,'status',c.status,'revision',c.revision);
end $$;
create or replace function public.pro_oauth_note(p_actor uuid,p_provider text,p_mode text,p_action text,p_detail jsonb) returns void
language sql security invoker set search_path=public,pg_temp as $$
 insert into public.pro_oauth_history(owner_id,provider,mode,action,detail) values(p_actor,p_provider,p_mode,p_action,coalesce(p_detail,'{}')) $$;
-- Server-only: the encrypted envelopes for one call (the API never returns them to the browser).
create or replace function public.pro_oauth_token(p_actor uuid,p_provider text) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('mode',mode,'status',status,'accessBox',access_box,'refreshBox',refresh_box,'expiresAt',access_expires_at,'accountEmail',account_email,'realmId',realm_id,'revision',revision)
 from public.pro_oauth_connections where owner_id=p_actor and provider=p_provider and status='connected' $$;
drop function if exists public.pro_oauth_revoke(uuid,jsonb);
create or replace function public.pro_oauth_revoke(p_actor uuid,p_input jsonb,p_provider_revoked boolean default false) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare prior jsonb;c public.pro_oauth_connections;result jsonb;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 prior:=public.pro_connector_receipt(p_actor,p_input,'revoke');if prior is not null then return prior;end if;
 select * into c from public.pro_oauth_connections where owner_id=p_actor and provider=p_input->>'provider' for update;
 if not found or c.status<>'connected' then raise exception 'Not connected' using errcode='22023',hint='pro_oauth_not_connected';end if;
 if jsonb_typeof(p_input->'revision')<>'number' or c.revision<>(p_input->>'revision')::integer then raise exception 'Connection changed' using errcode='40001';end if;
 update public.pro_oauth_connections set status='revoked',access_box=null,refresh_box=null,access_expires_at=null,revoked_at=now(),revision=revision+1,updated_at=now()
  where owner_id=p_actor and provider=c.provider returning * into c;
 insert into public.pro_oauth_history(owner_id,provider,mode,action,detail) values(p_actor,c.provider,c.mode,'revoke',jsonb_build_object('providerRevoked',coalesce(p_provider_revoked,false)));
 result:=jsonb_build_object('provider',c.provider,'status',c.status,'revision',c.revision);
 insert into public.pro_connector_actions(owner_id,action_id,scope,input,result) values(p_actor,(p_input->>'actionId')::uuid,'revoke',p_input,result);
 return result;
end $$;

create or replace function public.pro_connectors_read(p_actor uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 return jsonb_build_object(
  'connections',coalesce((select jsonb_agg(jsonb_build_object('provider',c.provider,'mode',c.mode,'status',c.status,'accountEmail',c.account_email,'scopes',to_jsonb(c.scopes),
    'connectedAt',c.connected_at,'revokedAt',c.revoked_at,'revision',c.revision,'realmId',c.realm_id,'encrypted',c.access_box is not null) order by c.provider) from public.pro_oauth_connections c where c.owner_id=p_actor),'[]'),
  'history',coalesce((select jsonb_agg(jsonb_build_object('provider',h.provider,'mode',h.mode,'action',h.action,'detail',h.detail,'at',h.at) order by h.at desc) from (select * from public.pro_oauth_history where owner_id=p_actor order by at desc limit 20) h),'[]'),
  'outbox',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'provider',o.provider,'mode',o.mode,'from',o.from_email,'to',to_jsonb(o.to_emails),'subject',o.subject,'body',o.body,'workId',o.work_id,
    'attachments',o.attachments,'status',o.status,'confirmedAt',o.confirmed_at,'error',o.error,'createdAt',o.created_at) order by o.created_at desc) from (select * from public.pro_email_outbox where owner_id=p_actor order by created_at desc limit 30) o),'[]'),
  'calendar',jsonb_build_object(
   'links',coalesce((select jsonb_agg(jsonb_build_object('provider',l.provider,'kind',l.local_kind,'localId',l.local_id,'remoteId',l.remote_id,'title',l.title,'status',l.status,'conflict',l.conflict,'syncedAt',l.synced_at,'revision',l.revision) order by l.local_kind,l.title) from public.pro_calendar_links l where l.owner_id=p_actor and l.status<>'removed'),'[]'),
   'external',coalesce((select jsonb_agg(jsonb_build_object('provider',e.provider,'remoteId',e.remote_id,'title',e.title,'startsAt',e.starts_at,'endsAt',e.ends_at,'allDay',e.all_day) order by e.starts_at) from public.pro_calendar_external e where e.owner_id=p_actor),'[]')),
  'works',coalesce((select jsonb_agg(jsonb_build_object('id',w.id,'label',w.service||' · '||w.client) order by w.position desc) from (select * from public.pro_work where user_id=p_actor and not cancelled order by position desc limit 50) w),'[]'));
end $$;

-- Email send record. confirmed must be true (the owner confirmed THIS message in the UI). Idempotent.
create or replace function public.pro_email_record(p_actor uuid,p_input jsonb,p_mode text,p_from text) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare prior jsonb;c public.pro_oauth_connections;oid uuid:=gen_random_uuid();o public.pro_email_outbox;result jsonb;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 prior:=public.pro_connector_receipt(p_actor,p_input,'email');if prior is not null then return prior||jsonb_build_object('duplicate',true);end if;
 if p_input->'confirmed' is distinct from 'true'::jsonb then raise exception 'Each send needs explicit confirmation' using errcode='22023',hint='pro_email_confirm';end if;
 select * into c from public.pro_oauth_connections where owner_id=p_actor and provider=p_input->>'provider' and status='connected';
 if not found then raise exception 'Mailbox not connected' using errcode='22023',hint='pro_oauth_not_connected';end if;
 if c.mode<>p_mode then raise exception 'Connection mode differs' using errcode='22023',hint='pro_oauth_mode';end if;
 if p_input->>'workId' is not null and not exists(select 1 from public.pro_work where user_id=p_actor and id=p_input->>'workId') then raise exception 'Unknown project' using errcode='22023';end if;
 insert into public.pro_email_outbox(owner_id,id,provider,mode,from_email,to_emails,subject,body,work_id,attachments,status,confirmed_at)
 values(p_actor,oid,c.provider,p_mode,coalesce(p_from,c.account_email,'buzon@desconocido.local'),(select array_agg(lower(btrim(x))) from jsonb_array_elements_text(p_input->'to') x),
  p_input->>'subject',p_input->>'body',p_input->>'workId',coalesce(p_input->'attachments','[]'),case when p_mode='mock' then 'simulated' else 'queued' end,now()) returning * into o;
 result:=jsonb_build_object('id',o.id,'status',o.status,'mode',o.mode);
 insert into public.pro_connector_actions(owner_id,action_id,scope,input,result) values(p_actor,(p_input->>'actionId')::uuid,'email',p_input,result);
 return result;
exception when check_violation or not_null_violation then raise exception 'Invalid email' using errcode='22023';
end $$;
create or replace function public.pro_email_result(p_actor uuid,p_id uuid,p_ok boolean,p_message_id text,p_error text) returns void
language sql security invoker set search_path=public,pg_temp as $$
 update public.pro_email_outbox set status=case when p_ok then 'sent' else 'failed' end,provider_message_id=left(p_message_id,200),error=left(p_error,300)
 where owner_id=p_actor and id=p_id and status='queued' $$;

-- Calendar sources: scheduled jobs of the agenda and open dated tasks (America/Costa_Rica dates).
create or replace function public.pro_calendar_sources(p_actor uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 return coalesce((select jsonb_agg(x) from (
  select jsonb_build_object('kind','appointment','localId',w.id,'title',w.service||' · '||w.client,'startsAt',public.pro_instant(w.start),
   'endsAt',coalesce(public.pro_instant(nullif(btrim(w."end"),'')),public.pro_instant(w.start)+interval '1 hour'),'allDay',false,'revision',null) x
  from public.pro_work w where w.user_id=p_actor and not w.cancelled and w.stage<>'completed' and btrim(w.start)<>'' and public.pro_instant(w.start) is not null
  union all
  select jsonb_build_object('kind','task','localId',t.id::text,'title',t.title,'startsAt',(t.due_date::timestamp at time zone 'America/Costa_Rica'),
   'endsAt',((t.due_date+1)::timestamp at time zone 'America/Costa_Rica'),'allDay',true,'revision',t.revision)
  from public.pro_work_tasks t where t.owner_id=p_actor and not t.archived and t.status='open' and t.due_date is not null
 ) s),'[]');
end $$;
create or replace function public.pro_calendar_link_put(p_actor uuid,p_link jsonb) returns void
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 insert into public.pro_calendar_links(owner_id,provider,mode,local_kind,local_id,remote_id,local_fingerprint,remote_etag,status,conflict,title,synced_at)
 values(p_actor,p_link->>'provider',p_link->>'mode',p_link->>'kind',p_link->>'localId',p_link->>'remoteId',p_link->>'fingerprint',p_link->>'etag',coalesce(p_link->>'status','synced'),
  case when p_link->>'status'='conflict' then p_link->'conflict' end,left(p_link->>'title',300),now())
 on conflict(owner_id,provider,local_kind,local_id) do update set mode=excluded.mode,remote_id=excluded.remote_id,local_fingerprint=excluded.local_fingerprint,remote_etag=excluded.remote_etag,
  status=excluded.status,conflict=excluded.conflict,title=excluded.title,synced_at=now(),revision=pro_calendar_links.revision+1;
exception when check_violation or not_null_violation then raise exception 'Invalid calendar link' using errcode='22023';
end $$;
-- A task moved in the calendar: CAS on the task revision (a local edit in between becomes a conflict).
create or replace function public.pro_calendar_apply_task_date(p_actor uuid,p_task uuid,p_revision integer,p_date date) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare t public.pro_work_tasks;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into t from public.pro_work_tasks where owner_id=p_actor and id=p_task for update;
 if not found or t.archived then return jsonb_build_object('ok',false,'reason','missing');end if;
 if t.revision<>p_revision then return jsonb_build_object('ok',false,'reason','changed');end if;
 update public.pro_work_tasks set due_date=p_date,revision=revision+1,updated_at=now() where owner_id=p_actor and id=p_task returning * into t;
 return jsonb_build_object('ok',true,'revision',t.revision);
end $$;
create or replace function public.pro_calendar_external_put(p_actor uuid,p_provider text,p_rows jsonb) returns void
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 delete from public.pro_calendar_external where owner_id=p_actor and provider=p_provider;
 insert into public.pro_calendar_external(owner_id,provider,remote_id,title,starts_at,ends_at,all_day)
 select p_actor,p_provider,r->>'remoteId',left(r->>'title',300),(r->>'startsAt')::timestamptz,(r->>'endsAt')::timestamptz,coalesce((r->>'allDay')::boolean,false) from jsonb_array_elements(coalesce(p_rows,'[]')) r limit 200;
end $$;

do $$declare n text;begin foreach n in array array['pro_oauth_states','pro_oauth_connections','pro_oauth_history','pro_connector_actions','pro_email_outbox','pro_calendar_links','pro_calendar_external','pro_mock_calendar_events'] loop
 execute format('alter table public.%I enable row level security',n);execute format('revoke all on public.%I from public,anon,authenticated',n);execute format('grant select,insert,update,delete on public.%I to service_role',n);
end loop;end $$;
do $$declare f regprocedure;begin
 for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and (p.proname like 'pro\_oauth\_%' or p.proname like 'pro\_email\_%' or p.proname like 'pro\_calendar\_%' or p.proname like 'pro\_connector%') loop
  execute format('revoke all on function %s from public,anon,authenticated',f);
  if f::text not like 'pro_connectors_immutable(%' and f::text not like 'pro_email_outbox_guard(%' then execute format('grant execute on function %s to service_role',f);end if;
 end loop;end $$;
notify pgrst,'reload schema';
commit;

-- ===== accounting-sync-local.sql =====
-- LOCAL PRO ONLY. Round 6B (2026-11-13): accounting sync (Houzz parity row 56).
-- * QuickBooks Online through the 6A framework (provider 'quickbooks', Intuit OAuth in connectors-local.sql):
--   customers (pro_clients), invoices (invoice drafts; «emitted» = accepted Hacienda FE/TE) and payments
--   (non-voided applications of recorded payments to those drafts).
-- * Mapping (per owner, CAS + idempotent + immutable history): income account, deposit account, and one
--   QuickBooks tax code per Costa Rica IVA code (01 exento 0 %, 02 1 %, 03 2 %, 04 4 %, 08 13 %, 09 0,5 %,
--   10 exento, 11 0 % sin derecho a crédito).
-- * Links remember the remote id, its SyncToken and the hash of what we last sent. When BOTH sides changed
--   since the last sync the link becomes a conflict (both versions kept) and nothing is overwritten until the
--   owner chooses «keep ContrataCR» or «keep QuickBooks».
-- * pro_mock_qbo_entities is the local stand-in of the QuickBooks company (mock mode only).
-- * The CSV export (any CR accounting system) reads pro_accounting_sources; it writes nothing.
-- Tables: RLS on, service_role only; functions security invoker, executable by service_role only.
begin;

create or replace function public.pro_accounting_vat_map_ok(p_map jsonb) returns boolean
language sql immutable security invoker set search_path=public,pg_temp as $$
 select jsonb_typeof(p_map)='object' and octet_length(p_map::text)<=2048
  and not exists(select 1 from jsonb_each(p_map) e where e.key not in('01','02','03','04','08','09','10','11') or jsonb_typeof(e.value)<>'string' or length(e.value#>>'{}')>60) $$;

create table if not exists public.pro_accounting_mappings(
 owner_id uuid primary key references public.profiles(id) on delete cascade,
 income_account text not null default '' check(length(income_account)<=100),
 deposit_account text not null default '' check(length(deposit_account)<=100),
 vat_map jsonb not null default '{}' check(public.pro_accounting_vat_map_ok(vat_map)),
 invoice_scope text not null default 'emitted' check(invoice_scope in('emitted','all')),
 revision integer not null default 1 check(revision>0),updated_at timestamptz not null default now()
);
create table if not exists public.pro_accounting_history(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null default gen_random_uuid(),
 action text not null check(action in('mapping','sync','resolve')),detail jsonb not null default '{}' check(octet_length(detail::text)<=8192 and public.pro_integration_config_safe(detail)),
 at timestamptz not null default clock_timestamp(),primary key(owner_id,id)
);
create table if not exists public.pro_accounting_links(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 provider text not null default 'quickbooks' check(provider='quickbooks'),mode text not null check(mode in('mock','sandbox','production')),
 entity text not null check(entity in('customer','invoice','payment')),local_id text not null check(length(local_id) between 1 and 160),
 remote_id text check(remote_id is null or length(remote_id) between 1 and 60),
 remote_sync_token text check(remote_sync_token is null or remote_sync_token~'^[0-9]{1,12}$'),
 local_hash text not null check(local_hash~'^[a-f0-9]{32}$'),
 label text not null check(length(label) between 1 and 200),
 status text not null check(status in('synced','conflict','error')),
 conflict jsonb check(conflict is null or jsonb_typeof(conflict)='object' and octet_length(conflict::text)<=8192),
 last_error text check(last_error is null or length(last_error)<=300),
 synced_at timestamptz not null default now(),revision integer not null default 1 check(revision>0),
 primary key(owner_id,provider,mode,entity,local_id),
 check((status='conflict')=(conflict is not null)),check(status<>'synced' or remote_id is not null)
);
-- Local stand-in of the QuickBooks company (mock only). sync_token increases on every remote change.
create table if not exists public.pro_mock_qbo_entities(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 entity text not null check(entity in('customer','invoice','payment','account','taxcode')),id text not null check(id~'^[0-9]{1,12}$'),
 sync_token integer not null default 0 check(sync_token>=0),data jsonb not null check(jsonb_typeof(data)='object' and octet_length(data::text)<=16384),
 updated_at timestamptz not null default now(),primary key(owner_id,entity,id)
);

create or replace function public.pro_accounting_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if tg_op='UPDATE' then raise exception 'Accounting history is immutable' using errcode='23514';end if;
 if exists(select 1 from public.profiles where id=old.owner_id) then raise exception 'Accounting history is immutable' using errcode='23514';end if;
 return old;
end $$;
drop trigger if exists pro_accounting_immutable on public.pro_accounting_history;
create trigger pro_accounting_immutable before update or delete on public.pro_accounting_history for each row execute function public.pro_accounting_immutable();

create or replace function public.pro_accounting_mapping_json(m public.pro_accounting_mappings) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('incomeAccount',coalesce(m.income_account,''),'depositAccount',coalesce(m.deposit_account,''),'vatMap',coalesce(m.vat_map,'{}'::jsonb),
  'invoiceScope',coalesce(m.invoice_scope,'emitted'),'revision',coalesce(m.revision,0),'updatedAt',m.updated_at) $$;

create or replace function public.pro_accounting_mapping_save(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare prior jsonb;m public.pro_accounting_mappings;result jsonb;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 prior:=public.pro_connector_receipt(p_actor,p_input,'accounting_mapping');if prior is not null then return prior;end if;
 if jsonb_typeof(p_input->'revision')<>'number' then raise exception 'Invalid revision' using errcode='22023';end if;
 select * into m from public.pro_accounting_mappings where owner_id=p_actor for update;
 if coalesce(m.revision,0)<>(p_input->>'revision')::integer then raise exception 'Mapping changed' using errcode='40001';end if;
 insert into public.pro_accounting_mappings(owner_id,income_account,deposit_account,vat_map,invoice_scope)
 values(p_actor,coalesce(p_input->>'incomeAccount',''),coalesce(p_input->>'depositAccount',''),coalesce(p_input->'vatMap','{}'),coalesce(p_input->>'invoiceScope','emitted'))
 on conflict(owner_id) do update set income_account=excluded.income_account,deposit_account=excluded.deposit_account,vat_map=excluded.vat_map,invoice_scope=excluded.invoice_scope,
  revision=pro_accounting_mappings.revision+1,updated_at=now()
 returning * into m;
 insert into public.pro_accounting_history(owner_id,action,detail) values(p_actor,'mapping',jsonb_build_object('incomeAccount',m.income_account,'depositAccount',m.deposit_account,'vatMap',m.vat_map,'invoiceScope',m.invoice_scope));
 result:=public.pro_accounting_mapping_json(m);
 insert into public.pro_connector_actions(owner_id,action_id,scope,input,result) values(p_actor,(p_input->>'actionId')::uuid,'accounting_mapping',p_input,result);
 return result;
exception when check_violation then raise exception 'Invalid mapping' using errcode='22023';
end $$;

-- What would be synced/exported. Dates in America/Costa_Rica. Hash = md5 of the canonical object.
create or replace function public.pro_accounting_sources(p_actor uuid,p_scope text default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare scope text;customers jsonb;invoices jsonb;payments jsonb;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 scope:=coalesce(p_scope,(select invoice_scope from public.pro_accounting_mappings where owner_id=p_actor),'emitted');
 with inv as(
  select d.*,e.consecutivo,e.clave,e.issued_at,
   coalesce((select jsonb_agg(jsonb_build_object('line',l.line_number,'description',l.description,'quantity',l.quantity,'unitPrice',l.unit_price,'discountType',l.discount_type,'discount',l.discount,
     'taxTreatment',l.tax_treatment,'taxRate',l.tax_rate,'vatCode',coalesce(t.vat_code,case when l.tax_treatment='vat' and l.tax_rate=13 then '08' when l.tax_treatment='vat' and l.tax_rate=4 then '04' when l.tax_treatment='vat' and l.tax_rate=2 then '03' when l.tax_treatment='vat' and l.tax_rate=1 then '02' when l.tax_treatment='vat' and l.tax_rate=0.5 then '09' else '10' end)) order by l.line_number)
     from public.pro_invoice_edited_lines l left join public.pro_invoice_line_tax t on t.user_id=l.user_id and t.draft_id=l.draft_id and t.line_number=l.line_number where l.user_id=d.user_id and l.draft_id=d.id),'[]') lines
  from public.pro_invoice_drafts d
  left join public.pro_invoice_draft_management mg on mg.user_id=d.user_id and mg.draft_id=d.id
  left join lateral(select x.consecutivo,x.clave,x.issued_at from public.pro_einvoice_documents x where x.owner_id=d.user_id and x.draft_id=d.id and x.doc_type in('01','04') and x.status='aceptado' order by x.created_at desc limit 1) e on true
  where d.user_id=p_actor and not coalesce(mg.archived,false) and (scope='all' or e.consecutivo is not null))
 select coalesce(jsonb_agg(o||jsonb_build_object('hash',md5(o::text)) order by o->>'date',o->>'localId'),'[]') into invoices from(
  select jsonb_build_object('localId',i.id,'number',coalesce(i.consecutivo,'BORRADOR-'||upper(left(i.id::text,8))),'emitted',i.consecutivo is not null,'clave',i.clave,'clientId',i.client_id,
   'customer',i.receiver_name,'customerId',i.receiver_identification,'title',i.title,'date',to_char(coalesce(i.issued_at,i.created_at) at time zone 'America/Costa_Rica','YYYY-MM-DD'),
   'totalCents',i.total_cents,'taxCents',coalesce(i.tax_cents,0),'currency',i.currency,'lines',i.lines) o from inv i) q;
 select coalesce(jsonb_agg(o||jsonb_build_object('hash',md5(o::text)) order by o->>'name',o->>'localId'),'[]') into customers from(
  select jsonb_build_object('localId',c.id,'name',c.name,'tradeName',c."tradeName",'email',c.email,'phone',c.phone,'identification',c.identification,'address',c.address) o
  from public.pro_clients c where c.user_id=p_actor and not c.archived) q;
 select coalesce(jsonb_agg(o||jsonb_build_object('hash',md5(o::text)) order by o->>'date',o->>'localId'),'[]') into payments from(
  select jsonb_build_object('localId',a.id,'invoiceId',a.draft_id,'clientId',p.client_id,'amountCents',a.amount_cents,'date',p.received_on,'method',p.method,'reference',p.reference) o
  from public.pro_invoice_payment_applications a join public.pro_invoice_payments p on p.user_id=a.user_id and p.id=a.payment_id
  where a.user_id=p_actor and not exists(select 1 from public.pro_invoice_payment_voids v where v.user_id=a.user_id and v.application_id=a.id)
   and (scope='all' or exists(select 1 from public.pro_einvoice_documents x where x.owner_id=a.user_id and x.draft_id=a.draft_id and x.doc_type in('01','04') and x.status='aceptado'))) q;
 return jsonb_build_object('scope',scope,'customers',customers,'invoices',invoices,'payments',payments);
end $$;

create or replace function public.pro_accounting_link_put(p_actor uuid,p_mode text,p_link jsonb) returns void
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 insert into public.pro_accounting_links(owner_id,provider,mode,entity,local_id,remote_id,remote_sync_token,local_hash,label,status,conflict,last_error,synced_at)
 values(p_actor,'quickbooks',p_mode,p_link->>'entity',p_link->>'localId',p_link->>'remoteId',p_link->>'syncToken',p_link->>'hash',left(p_link->>'label',200),p_link->>'status',
  case when p_link->>'status'='conflict' then p_link->'conflict' end,left(p_link->>'error',300),now())
 on conflict(owner_id,provider,mode,entity,local_id) do update set remote_id=coalesce(excluded.remote_id,pro_accounting_links.remote_id),remote_sync_token=coalesce(excluded.remote_sync_token,pro_accounting_links.remote_sync_token),
  local_hash=excluded.local_hash,label=excluded.label,status=excluded.status,conflict=excluded.conflict,last_error=excluded.last_error,synced_at=now(),revision=pro_accounting_links.revision+1;
exception when check_violation or not_null_violation then raise exception 'Invalid accounting link' using errcode='22023';
end $$;
create or replace function public.pro_accounting_note(p_actor uuid,p_action text,p_detail jsonb) returns void
language sql security invoker set search_path=public,pg_temp as $$
 insert into public.pro_accounting_history(owner_id,action,detail) values(p_actor,p_action,coalesce(p_detail,'{}')) $$;

create or replace function public.pro_accounting_read(p_actor uuid,p_mode text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare m public.pro_accounting_mappings;
begin
 if not public.pro_private_work_tools_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into m from public.pro_accounting_mappings where owner_id=p_actor;
 return jsonb_build_object('mapping',public.pro_accounting_mapping_json(m),
  'links',coalesce((select jsonb_agg(jsonb_build_object('entity',l.entity,'localId',l.local_id,'remoteId',l.remote_id,'syncToken',l.remote_sync_token,'hash',l.local_hash,'label',l.label,'status',l.status,'conflict',l.conflict,'error',l.last_error,'syncedAt',l.synced_at,'revision',l.revision) order by l.entity,l.label) from public.pro_accounting_links l where l.owner_id=p_actor and l.mode=p_mode),'[]'),
  'history',coalesce((select jsonb_agg(jsonb_build_object('action',h.action,'detail',h.detail,'at',h.at) order by h.at desc) from (select * from public.pro_accounting_history where owner_id=p_actor order by at desc limit 15) h),'[]'));
end $$;

do $$declare n text;begin foreach n in array array['pro_accounting_mappings','pro_accounting_history','pro_accounting_links','pro_mock_qbo_entities'] loop
 execute format('alter table public.%I enable row level security',n);execute format('revoke all on public.%I from public,anon,authenticated',n);execute format('grant select,insert,update,delete on public.%I to service_role',n);
end loop;end $$;
do $$declare f regprocedure;begin
 for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'pro\_accounting\_%' loop
  execute format('revoke all on function %s from public,anon,authenticated',f);
  if f::text not like 'pro_accounting_immutable(%' then execute format('grant execute on function %s to service_role',f);end if;
 end loop;end $$;
notify pgrst,'reload schema';
commit;

-- ===== ai-assistant-local.sql =====
-- LOCAL PRO ONLY. Round 6C (2026-11-13): AI assistant and transcription (rows 46, 67, 76, 77).
-- * Two new providers in the Round 6A/6B integration framework: «ai» (Anthropic Claude) and «transcription»
--   (OpenAI-compatible). Same rules: mock by default, sandbox only with every env var, production only with
--   the typed confirmation AND PRO_INTEGRATIONS_ALLOW_PRODUCTION=1.
-- * Per company: data-processing consent (OFF by default; every AI call is refused while it is off) and a
--   monthly usage cap with an atomic counter (one unit per provider call; idempotent by actionId).
-- * pro_ai_suggestions: every AI result is stored APART and is immutable. Nothing here writes quotes, clauses,
--   logs, updates, takeoffs, expenses or tasks: the owner reviews/edits a suggestion and saves it through the
--   existing editor. Only the review outcome (used/discarded) can be recorded, once.
-- * Meeting recordings: only with the all-parties consent confirmation; private to the owner (other owners get
--   P0002, customers 42501); deletable by the owner. Meeting notes exist only after the owner saves them.
-- Tables: RLS on, service_role only (no DELETE grant except recordings); functions security invoker, service_role only.
begin;

create or replace function public.pro_integration_provider_ids() returns text[]
language sql immutable security invoker set search_path=public,pg_temp as $$
 select array['hacienda','tilopay','esign','google','microsoft','quickbooks','ai','transcription']::text[] $$;
do $$declare t text;begin foreach t in array array['pro_integration_connections','pro_integration_requests','pro_integration_webhooks'] loop
 execute format('alter table public.%I drop constraint if exists %I',t,t||'_provider_check');
 execute format('alter table public.%I add constraint %I check(provider = any(public.pro_integration_provider_ids()))',t,t||'_provider_check');
end loop;end $$;

create or replace function public.pro_ai_features() returns text[]
language sql immutable security invoker set search_path=public,pg_temp as $$
 select array['quote_line','contract_clause','daily_log','client_update','takeoff','expense_receipt','expense_voice','meeting','transcribe_voice','transcribe_meeting']::text[] $$;

create table if not exists public.pro_ai_settings(
 owner_id uuid primary key references public.profiles(id) on delete cascade,
 consent boolean not null default false,
 consent_version text check(consent_version is null or consent_version~'^\d{4}-\d{2}-\d{2}$'),
 consent_at timestamptz,
 monthly_limit integer not null default 100 check(monthly_limit between 1 and 5000),
 revision integer not null default 1 check(revision>0),
 updated_at timestamptz not null default now(),
 check(not consent or (consent_version is not null and consent_at is not null))
);
create table if not exists public.pro_ai_settings_history(
 owner_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 action text not null check(action in('set_consent','set_limit')),detail jsonb not null check(octet_length(detail::text)<=1024),
 at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id)
);
create table if not exists public.pro_ai_actions(
 owner_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 input jsonb not null,result jsonb not null,created_at timestamptz not null default now(),primary key(owner_id,action_id)
);
create table if not exists public.pro_ai_usage(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 month date not null check(extract(day from month)=1),
 used integer not null default 0 check(used>=0),
 by_feature jsonb not null default '{}' check(jsonb_typeof(by_feature)='object'),
 updated_at timestamptz not null default now(),primary key(owner_id,month)
);
create table if not exists public.pro_ai_suggestions(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 id uuid not null,action_id uuid not null,
 feature text not null check(feature=any(public.pro_ai_features())),
 provider text not null check(provider in('ai','transcription')),
 mode text not null check(mode in('mock','sandbox','production')),
 model text not null check(length(model) between 1 and 80),
 work_id text check(work_id is null or length(work_id) between 1 and 160),
 source jsonb not null default '{}' check(jsonb_typeof(source)='object' and octet_length(source::text)<=2048),
 units integer not null check(units between 1 and 3),
 status text not null default 'pending' check(status in('pending','ready','failed')),
 output jsonb check(output is null or (jsonb_typeof(output)='object' and octet_length(output::text)<=131072)),
 error text check(error is null or length(error) between 1 and 120),
 review text check(review is null or review in('used','discarded')),
 reviewed_at timestamptz,
 created_at timestamptz not null default clock_timestamp(),finished_at timestamptz,
 primary key(owner_id,id),unique(owner_id,action_id),
 check((status='ready')=(output is not null)),check((status='failed')=(error is not null)),check((status='pending')=(finished_at is null)),
 check((review is null)=(reviewed_at is null)),check(review is null or status='ready')
);
create index if not exists pro_ai_suggestions_recent on public.pro_ai_suggestions(owner_id,created_at desc);

create table if not exists public.pro_ai_recordings(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 id uuid not null,work_id text not null check(length(work_id) between 1 and 160),
 title text not null check(length(btrim(title)) between 1 and 160),
 consent_all_parties boolean not null check(consent_all_parties),
 consent_text text not null check(length(consent_text) between 20 and 1000),
 consent_at timestamptz not null default clock_timestamp(),
 mime text not null check(mime in('audio/webm','audio/ogg','audio/mpeg','audio/mp4','audio/wav','audio/x-wav','audio/aac','audio/x-m4a')),
 size_bytes integer not null check(size_bytes between 1 and 8388608),
 sha256 text not null check(sha256~'^[a-f0-9]{64}$'),
 content bytea not null,
 created_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,id),unique(id),
 check(octet_length(content)=size_bytes and sha256=encode(sha256(content),'hex')),
 foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade
);
create index if not exists pro_ai_recordings_work on public.pro_ai_recordings(owner_id,work_id,created_at desc);
create table if not exists public.pro_ai_meeting_notes(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 id uuid not null,work_id text not null,
 recording_id uuid,suggestion_id uuid,
 title text not null check(length(btrim(title)) between 1 and 160),
 transcript text not null default '' check(length(transcript)<=60000),
 summary text not null check(length(btrim(summary)) between 1 and 4000),
 action_items jsonb not null default '[]' check(jsonb_typeof(action_items)='array' and jsonb_array_length(action_items)<=20),
 decisions jsonb not null default '[]' check(jsonb_typeof(decisions)='array' and jsonb_array_length(decisions)<=20),
 ai_generated boolean not null default true,
 revision integer not null default 1 check(revision>0),
 created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,id),foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade
);
create table if not exists public.pro_ai_meeting_history(
 owner_id uuid not null references public.profiles(id) on delete cascade,meeting_id uuid not null,action_id uuid not null,
 action text not null check(action in('create','update','link_task')),revision integer not null,snapshot jsonb not null,
 at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id)
);

-- ---------------------------------------------------------------- guards
create or replace function public.pro_ai_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'AI history, receipts and recordings are immutable' using errcode='23514';end $$;
do $$declare t text;begin foreach t in array array['pro_ai_settings_history','pro_ai_actions','pro_ai_meeting_history','pro_ai_recordings'] loop
 execute format('drop trigger if exists %I on public.%I',t||'_immutable',t);
 execute format('create trigger %I before update on public.%I for each row execute function public.pro_ai_immutable()',t||'_immutable',t);
end loop;end $$;
create or replace function public.pro_ai_suggestion_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if (new.owner_id,new.id,new.action_id,new.feature,new.provider,new.mode,new.model,new.work_id,new.source,new.units,new.created_at) is distinct from
    (old.owner_id,old.id,old.action_id,old.feature,old.provider,old.mode,old.model,old.work_id,old.source,old.units,old.created_at) then
  raise exception 'Suggestion identity is immutable' using errcode='23514';end if;
 if old.status<>'pending' and (new.status,new.output,new.error,new.finished_at) is distinct from (old.status,old.output,old.error,old.finished_at) then
  raise exception 'A finished suggestion is immutable' using errcode='23514';end if;
 if old.review is not null and (new.review,new.reviewed_at) is distinct from (old.review,old.reviewed_at) then
  raise exception 'The review outcome is recorded once' using errcode='23514';end if;
 return new;
end $$;
drop trigger if exists pro_ai_suggestion_guard on public.pro_ai_suggestions;
create trigger pro_ai_suggestion_guard before update on public.pro_ai_suggestions for each row execute function public.pro_ai_suggestion_guard();

-- ---------------------------------------------------------------- settings, consent, usage
create or replace function public.pro_ai_month() returns date
language sql stable security invoker set search_path=public,pg_temp as $$ select date_trunc('month',now() at time zone 'America/Costa_Rica')::date $$;
create or replace function public.pro_ai_settings_json(p_actor uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare s public.pro_ai_settings;u public.pro_ai_usage;lim integer;
begin
 select * into s from public.pro_ai_settings where owner_id=p_actor;
 select * into u from public.pro_ai_usage where owner_id=p_actor and month=public.pro_ai_month();
 lim:=coalesce(s.monthly_limit,100);
 return jsonb_build_object('consent',coalesce(s.consent,false),'consentVersion',s.consent_version,'consentAt',s.consent_at,'monthlyLimit',lim,'revision',coalesce(s.revision,0),
  'usage',jsonb_build_object('month',to_char(public.pro_ai_month(),'YYYY-MM'),'used',coalesce(u.used,0),'remaining',greatest(lim-coalesce(u.used,0),0),'byFeature',coalesce(u.by_feature,'{}'::jsonb)));
end $$;
create or replace function public.pro_ai_settings_read(p_actor uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 return public.pro_ai_settings_json(p_actor)||jsonb_build_object('history',coalesce((select jsonb_agg(jsonb_build_object('action',h.action,'detail',h.detail,'at',h.at) order by h.at desc) from (select * from public.pro_ai_settings_history where owner_id=p_actor order by at desc limit 10) h),'[]'));
end $$;
create or replace function public.pro_ai_settings_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text:=p_input->>'action';aid uuid;receipt public.pro_ai_actions;s public.pro_ai_settings;rev integer;lim integer;result jsonb;detail jsonb;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input)<>'object' or act not in('set_consent','set_limit') or jsonb_typeof(p_input->'revision')<>'number' then raise exception 'Invalid AI settings action' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;exception when others then raise exception 'Invalid action id' using errcode='22023';end;
 if aid is null then raise exception 'Invalid action id' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-ai:'||p_actor::text,0));
 select * into receipt from public.pro_ai_actions where owner_id=p_actor and action_id=aid;
 if found then if receipt.input<>p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;return receipt.result;end if;
 select * into s from public.pro_ai_settings where owner_id=p_actor for update;
 rev:=(p_input->>'revision')::integer;
 if rev is distinct from coalesce(s.revision,0) then raise exception 'AI settings changed' using errcode='40001';end if;
 if act='set_consent' then
  if jsonb_typeof(p_input->'consent')<>'boolean' or coalesce(p_input->>'consentVersion','')!~'^\d{4}-\d{2}-\d{2}$' then raise exception 'Invalid consent' using errcode='22023';end if;
  insert into public.pro_ai_settings(owner_id,consent,consent_version,consent_at,revision) values(p_actor,(p_input->>'consent')::boolean,p_input->>'consentVersion',case when (p_input->>'consent')::boolean then now() end,1)
  on conflict(owner_id) do update set consent=excluded.consent,consent_version=excluded.consent_version,consent_at=excluded.consent_at,revision=pro_ai_settings.revision+1,updated_at=now();
  detail:=jsonb_build_object('consent',(p_input->>'consent')::boolean,'version',p_input->>'consentVersion');
 else
  if jsonb_typeof(p_input->'monthlyLimit')<>'number' then raise exception 'Invalid limit' using errcode='22023';end if;
  lim:=(p_input->>'monthlyLimit')::integer;
  if lim is null or lim not between 1 and 5000 then raise exception 'Invalid limit' using errcode='22023';end if;
  insert into public.pro_ai_settings(owner_id,monthly_limit,revision) values(p_actor,lim,1)
  on conflict(owner_id) do update set monthly_limit=excluded.monthly_limit,revision=pro_ai_settings.revision+1,updated_at=now();
  detail:=jsonb_build_object('from',coalesce(s.monthly_limit,100),'to',lim);
 end if;
 insert into public.pro_ai_settings_history(owner_id,action_id,action,detail) values(p_actor,aid,act,detail);
 result:=public.pro_ai_settings_json(p_actor);
 insert into public.pro_ai_actions(owner_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

create or replace function public.pro_ai_suggestion_json(r public.pro_ai_suggestions) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',r.id,'feature',r.feature,'provider',r.provider,'mode',r.mode,'model',r.model,'workId',r.work_id,'status',r.status,'output',r.output,'error',r.error,'review',r.review,'createdAt',r.created_at) $$;
-- Reserve usage and register a pending suggestion. Same actionId = the same suggestion (no second unit).
create or replace function public.pro_ai_begin(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;sid uuid;r public.pro_ai_suggestions;s public.pro_ai_settings;u public.pro_ai_usage;n integer;feat text:=p_input->>'feature';wid text:=nullif(p_input->>'workId','');
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input)<>'object' or not coalesce(feat=any(public.pro_ai_features()),false) or p_input->>'provider' not in('ai','transcription') or p_input->>'mode' not in('mock','sandbox','production')
  or jsonb_typeof(p_input->'units')<>'number' or jsonb_typeof(coalesce(p_input->'source','{}'))<>'object' then raise exception 'Invalid AI request' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;sid:=(p_input->>'id')::uuid;exception when others then raise exception 'Invalid action id' using errcode='22023';end;
 if aid is null or sid is null then raise exception 'Invalid action id' using errcode='22023';end if;
 n:=(p_input->>'units')::integer;if n not between 1 and 3 then raise exception 'Invalid units' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-ai:'||p_actor::text,0));
 select * into r from public.pro_ai_suggestions where owner_id=p_actor and action_id=aid;
 if found then
  if r.feature<>feat or r.work_id is distinct from wid or r.provider<>p_input->>'provider' then raise exception 'Action identity reused with different payload' using errcode='22023';end if;
  return public.pro_ai_suggestion_json(r)||jsonb_build_object('duplicate',true);
 end if;
 select * into s from public.pro_ai_settings where owner_id=p_actor;
 if not coalesce(s.consent,false) then raise exception 'AI data-processing consent is off' using errcode='42501',hint='pro_ai_consent_required';end if;
 if wid is not null and not exists(select 1 from public.pro_work where user_id=p_actor and id=wid) then raise exception 'Unknown work' using errcode='P0002';end if;
 insert into public.pro_ai_usage(owner_id,month) values(p_actor,public.pro_ai_month()) on conflict do nothing;
 select * into u from public.pro_ai_usage where owner_id=p_actor and month=public.pro_ai_month() for update;
 if u.used+n>s.monthly_limit then raise exception 'Monthly AI usage limit reached' using errcode='54000',hint='pro_ai_cap_reached';end if;
 update public.pro_ai_usage set used=used+n,by_feature=jsonb_set(by_feature,array[feat],to_jsonb(coalesce((by_feature->>feat)::integer,0)+n)),updated_at=now() where owner_id=p_actor and month=u.month;
 insert into public.pro_ai_suggestions(owner_id,id,action_id,feature,provider,mode,model,work_id,source,units)
 values(p_actor,sid,aid,feat,p_input->>'provider',p_input->>'mode',left(coalesce(nullif(p_input->>'model',''),'unknown'),80),wid,coalesce(p_input->'source','{}'),n) returning * into r;
 return public.pro_ai_suggestion_json(r)||jsonb_build_object('duplicate',false);
end $$;
create or replace function public.pro_ai_finish(p_actor uuid,p_id uuid,p_ok boolean,p_output jsonb,p_error text) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare r public.pro_ai_suggestions;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from public.pro_ai_suggestions where owner_id=p_actor and id=p_id for update;
 if not found then raise exception 'Unknown suggestion' using errcode='P0002';end if;
 if r.status<>'pending' then return public.pro_ai_suggestion_json(r);end if;
 if p_ok and (p_output is null or jsonb_typeof(p_output)<>'object') then raise exception 'Invalid output' using errcode='22023';end if;
 update public.pro_ai_suggestions set status=case when p_ok then 'ready' else 'failed' end,output=case when p_ok then p_output end,
  error=case when p_ok then null else left(coalesce(nullif(p_error,''),'provider_failed'),120) end,finished_at=clock_timestamp()
  where owner_id=p_actor and id=p_id returning * into r;
 return public.pro_ai_suggestion_json(r);
end $$;
create or replace function public.pro_ai_review(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare r public.pro_ai_suggestions;sid uuid;outcome text:=p_input->>'outcome';
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 begin sid:=(p_input->>'id')::uuid;exception when others then raise exception 'Invalid id' using errcode='22023';end;
 if outcome not in('used','discarded') then raise exception 'Invalid outcome' using errcode='22023';end if;
 select * into r from public.pro_ai_suggestions where owner_id=p_actor and id=sid for update;
 if not found then raise exception 'Unknown suggestion' using errcode='P0002';end if;
 if r.status<>'ready' then raise exception 'Suggestion not ready' using errcode='22023';end if;
 if r.review is not null then if r.review<>outcome then raise exception 'Already reviewed' using errcode='22023';end if;return public.pro_ai_suggestion_json(r);end if;
 update public.pro_ai_suggestions set review=outcome,reviewed_at=clock_timestamp() where owner_id=p_actor and id=sid returning * into r;
 return public.pro_ai_suggestion_json(r);
end $$;
create or replace function public.pro_ai_suggestion_read(p_actor uuid,p_id uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r public.pro_ai_suggestions;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from public.pro_ai_suggestions where owner_id=p_actor and id=p_id;
 if not found then raise exception 'Unknown suggestion' using errcode='P0002';end if;
 return public.pro_ai_suggestion_json(r);
end $$;
-- Minimal job data for prompts (no contact details: only the customer's first name).
create or replace function public.pro_ai_job_context(p_actor uuid,p_work text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare w public.pro_work;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into w from public.pro_work where user_id=p_actor and id=p_work;
 if not found then raise exception 'Unknown work' using errcode='P0002';end if;
 return jsonb_build_object('service',coalesce(w.service,''),'stage',coalesce(w.stage,''),'start',nullif(w.start,''),'end',nullif(w."end",''),
  'clientFirstName',coalesce(split_part(btrim(coalesce(w.client,'')),' ',1),''),
  'recentLogs',coalesce((select jsonb_agg(left(to_char(l.log_date,'YYYY-MM-DD')||' · '||l.title||': '||l.summary,400) order by l.log_date desc) from (select * from public.pro_daily_logs where owner_id=p_actor and work_id=p_work and not archived order by log_date desc,id limit 5) l),'[]'),
  'openTasks',coalesce((select jsonb_agg(left(t.title||coalesce(' (vence '||to_char(t.due_date,'YYYY-MM-DD')||')',''),200) order by t.due_date nulls last) from (select * from public.pro_work_tasks where owner_id=p_actor and work_id=p_work and status='open' and not archived order by due_date nulls last,id limit 10) t),'[]'),
  'recentUpdates',coalesce((select jsonb_agg(left(u.text,400) order by u.created_at desc) from (select * from public.pro_work_updates where owner_id=p_actor and work_id=p_work order by created_at desc limit 3) u),'[]'));
end $$;

-- ---------------------------------------------------------------- meeting recordings and notes
create or replace function public.pro_ai_recording_json(r public.pro_ai_recordings) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',r.id,'workId',r.work_id,'title',r.title,'mime',r.mime,'sizeBytes',r.size_bytes,'sha256',r.sha256,'consentAllParties',r.consent_all_parties,'consentAt',r.consent_at,'createdAt',r.created_at) $$;
create or replace function public.pro_ai_recording_create(p_actor uuid,p_input jsonb,p_content bytea) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare rid uuid;wid text:=p_input->>'workId';r public.pro_ai_recordings;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 begin rid:=(p_input->>'id')::uuid;exception when others then raise exception 'Invalid id' using errcode='22023';end;
 if rid is null or p_content is null then raise exception 'Invalid recording' using errcode='22023';end if;
 if (p_input->>'consentAllParties') is distinct from 'true' or length(coalesce(p_input->>'consentText',''))<20 then raise exception 'All parties must consent' using errcode='22023',hint='pro_ai_meeting_consent';end if;
 if not coalesce((select consent from public.pro_ai_settings where owner_id=p_actor),false) then raise exception 'AI data-processing consent is off' using errcode='42501',hint='pro_ai_consent_required';end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=wid) then raise exception 'Unknown work' using errcode='P0002';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-ai-recording:'||p_actor::text,0));
 select * into r from public.pro_ai_recordings where owner_id=p_actor and id=rid;
 if found then if r.sha256<>encode(sha256(p_content),'hex') or r.work_id<>wid then raise exception 'Recording id reused' using errcode='22023';end if;return public.pro_ai_recording_json(r);end if;
 if exists(select 1 from public.pro_ai_recordings where id=rid) then raise exception 'Recording id reused' using errcode='22023';end if;
 if (select count(*) from public.pro_ai_recordings where owner_id=p_actor and work_id=wid)>=100 then raise exception 'Too many recordings' using errcode='54000';end if;
 insert into public.pro_ai_recordings(owner_id,id,work_id,title,consent_all_parties,consent_text,mime,size_bytes,sha256,content)
 values(p_actor,rid,wid,left(btrim(coalesce(nullif(p_input->>'title',''),'Reunión')),160),true,left(p_input->>'consentText',1000),p_input->>'mime',octet_length(p_content),encode(sha256(p_content),'hex'),p_content) returning * into r;
 return public.pro_ai_recording_json(r);
end $$;
create or replace function public.pro_ai_meeting_json(m public.pro_ai_meeting_notes) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',m.id,'workId',m.work_id,'recordingId',m.recording_id,'suggestionId',m.suggestion_id,'title',m.title,'transcript',m.transcript,'summary',m.summary,
  'actionItems',m.action_items,'decisions',m.decisions,'aiGenerated',m.ai_generated,'revision',m.revision,'createdAt',m.created_at,'updatedAt',m.updated_at) $$;
create or replace function public.pro_ai_meetings_read(p_actor uuid,p_work text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then raise exception 'Unknown work' using errcode='P0002';end if;
 return jsonb_build_object('workId',p_work,
  'recordings',coalesce((select jsonb_agg(public.pro_ai_recording_json(r) order by r.created_at desc) from public.pro_ai_recordings r where r.owner_id=p_actor and r.work_id=p_work),'[]'),
  'meetings',coalesce((select jsonb_agg(public.pro_ai_meeting_json(m) order by m.created_at desc) from public.pro_ai_meeting_notes m where m.owner_id=p_actor and m.work_id=p_work),'[]'));
end $$;
create or replace function public.pro_ai_recording_audio(p_actor uuid,p_id uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r public.pro_ai_recordings;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from public.pro_ai_recordings where owner_id=p_actor and id=p_id;
 if not found then raise exception 'Unknown recording' using errcode='P0002';end if;
 return public.pro_ai_recording_json(r)||jsonb_build_object('base64',encode(r.content,'base64'));
end $$;
create or replace function public.pro_ai_recording_delete(p_actor uuid,p_id uuid) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 delete from public.pro_ai_recordings where owner_id=p_actor and id=p_id;
 if not found then raise exception 'Unknown recording' using errcode='P0002';end if;
 return jsonb_build_object('deleted',p_id);
end $$;
create or replace function public.pro_ai_meeting_items(p_items jsonb) returns jsonb
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
declare item jsonb;out jsonb:='[]';
begin
 if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)>20 then raise exception 'Invalid action items' using errcode='22023';end if;
 for item in select value from jsonb_array_elements(p_items) loop
  if jsonb_typeof(item)<>'object' or coalesce(item->>'id','')!~'^[0-9a-f-]{36}$' or length(btrim(coalesce(item->>'text','')))not between 1 and 160
   or (item->'dueDate' is not null and jsonb_typeof(item->'dueDate')<>'null' and coalesce(item->>'dueDate','')!~'^\d{4}-\d{2}-\d{2}$')
   or (item->'taskId' is not null and jsonb_typeof(item->'taskId')<>'null' and coalesce(item->>'taskId','')!~'^[0-9a-f-]{36}$') then raise exception 'Invalid action item' using errcode='22023';end if;
  out:=out||jsonb_build_array(jsonb_build_object('id',item->>'id','text',btrim(item->>'text'),'dueDate',nullif(item->>'dueDate',''),'taskId',nullif(item->>'taskId','')));
 end loop;
 return out;
end $$;
create or replace function public.pro_ai_meeting_decisions(p_value jsonb) returns jsonb
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
begin
 if jsonb_typeof(p_value)<>'array' or jsonb_array_length(p_value)>20 or exists(select 1 from jsonb_array_elements(p_value) x where jsonb_typeof(x)<>'string' or length(btrim(x#>>'{}')) not between 1 and 300) then raise exception 'Invalid decisions' using errcode='22023';end if;
 return p_value;
end $$;
create or replace function public.pro_ai_meeting_save(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text:=p_input->>'action';aid uuid;mid uuid;receipt public.pro_ai_actions;m public.pro_ai_meeting_notes;sg public.pro_ai_suggestions;items jsonb;dec jsonb;result jsonb;item jsonb;tid uuid;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input)<>'object' or act not in('create','update','link_task') then raise exception 'Invalid meeting action' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;mid:=(p_input->>'id')::uuid;exception when others then raise exception 'Invalid id' using errcode='22023';end;
 if aid is null or mid is null then raise exception 'Invalid id' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-ai-meeting:'||p_actor::text,0));
 select * into receipt from public.pro_ai_actions where owner_id=p_actor and action_id=aid;
 if found then if receipt.input<>p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;return receipt.result;end if;
 if act='create' then
  if not exists(select 1 from public.pro_work where user_id=p_actor and id=p_input->>'workId') then raise exception 'Unknown work' using errcode='P0002';end if;
  if nullif(p_input->>'suggestionId','') is not null then
   select * into sg from public.pro_ai_suggestions where owner_id=p_actor and id=(p_input->>'suggestionId')::uuid;
   if not found or sg.feature<>'meeting' or sg.status<>'ready' or sg.work_id is distinct from p_input->>'workId' then raise exception 'Unknown suggestion' using errcode='P0002';end if;
  end if;
  if nullif(p_input->>'recordingId','') is not null and not exists(select 1 from public.pro_ai_recordings where owner_id=p_actor and id=(p_input->>'recordingId')::uuid and work_id=p_input->>'workId') then raise exception 'Unknown recording' using errcode='P0002';end if;
  if exists(select 1 from public.pro_ai_meeting_notes where owner_id=p_actor and id=mid) then raise exception 'Meeting exists' using errcode='23505';end if;
  items:=public.pro_ai_meeting_items(coalesce(p_input->'actionItems','[]'));dec:=public.pro_ai_meeting_decisions(coalesce(p_input->'decisions','[]'));
  insert into public.pro_ai_meeting_notes(owner_id,id,work_id,recording_id,suggestion_id,title,transcript,summary,action_items,decisions,ai_generated)
  values(p_actor,mid,p_input->>'workId',nullif(p_input->>'recordingId','')::uuid,nullif(p_input->>'suggestionId','')::uuid,left(btrim(coalesce(p_input->>'title','')),160),coalesce(p_input->>'transcript',''),btrim(coalesce(p_input->>'summary','')),items,dec,nullif(p_input->>'suggestionId','') is not null) returning * into m;
 else
  select * into m from public.pro_ai_meeting_notes where owner_id=p_actor and id=mid for update;
  if not found then raise exception 'Unknown meeting' using errcode='P0002';end if;
  if jsonb_typeof(p_input->'revision')<>'number' or (p_input->>'revision')::integer<>m.revision then raise exception 'Meeting changed' using errcode='40001';end if;
  if act='update' then
   items:=public.pro_ai_meeting_items(coalesce(p_input->'actionItems','[]'));
   update public.pro_ai_meeting_notes set title=left(btrim(coalesce(p_input->>'title','')),160),transcript=coalesce(p_input->>'transcript',''),summary=btrim(coalesce(p_input->>'summary','')),
    action_items=items,decisions=public.pro_ai_meeting_decisions(coalesce(p_input->'decisions',decisions)),revision=revision+1,updated_at=clock_timestamp() where owner_id=p_actor and id=mid returning * into m;
  else
   begin tid:=(p_input->>'taskId')::uuid;exception when others then raise exception 'Invalid task' using errcode='22023';end;
   if not exists(select 1 from public.pro_work_tasks where owner_id=p_actor and work_id=m.work_id and id=tid) then raise exception 'Unknown task' using errcode='P0002';end if;
   if not exists(select 1 from jsonb_array_elements(m.action_items) x where x->>'id'=p_input->>'itemId') then raise exception 'Unknown item' using errcode='P0002';end if;
   select coalesce(jsonb_agg(case when x->>'id'=p_input->>'itemId' then x||jsonb_build_object('taskId',tid) else x end),'[]') into items from jsonb_array_elements(m.action_items) x;
   update public.pro_ai_meeting_notes set action_items=items,revision=revision+1,updated_at=clock_timestamp() where owner_id=p_actor and id=mid returning * into m;
  end if;
 end if;
 result:=public.pro_ai_meeting_json(m);
 insert into public.pro_ai_meeting_history(owner_id,meeting_id,action_id,action,revision,snapshot) values(p_actor,mid,aid,act,m.revision,result);
 insert into public.pro_ai_actions(owner_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

-- ---------------------------------------------------------------- posture
do $$declare n text;begin foreach n in array array['pro_ai_settings','pro_ai_settings_history','pro_ai_actions','pro_ai_usage','pro_ai_suggestions','pro_ai_recordings','pro_ai_meeting_notes','pro_ai_meeting_history'] loop
 execute format('alter table public.%I enable row level security',n);execute format('revoke all on public.%I from public,anon,authenticated,service_role',n);execute format('grant select,insert,update on public.%I to service_role',n);
end loop;end $$;
grant delete on public.pro_ai_recordings to service_role;
do $$declare f regprocedure;begin
 for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and (p.proname like 'pro\_ai\_%' or p.proname='pro_integration_provider_ids') loop
  execute format('revoke all on function %s from public,anon,authenticated',f);
  if f::text not like 'pro_ai_immutable(%' and f::text not like 'pro_ai_suggestion_guard(%' then execute format('grant execute on function %s to service_role',f);end if;
 end loop;end $$;
notify pgrst,'reload schema';
commit;

-- ===== esign-acceptance-local.sql =====
-- LOCAL PRO ONLY. Round 6C (2026-11-13): follow-up of Round 6B — a SIGNED electronic signature request updates
-- the acceptance state of its document AUTOMATICALLY, through the document's existing writer:
-- * contract     → pro_contracts_client_mutate(recipient, accept)   (same path as the customer's own acceptance)
-- * quote        → pro_private_estimate_publication_mutate(recipient, accept)
-- * work_change  → pro_work_changes_mutate(owner, record_acceptance) (owner-recorded external approval)
-- Guards: the frozen hash of the request must still be the document's current hash, and for contracts/quotes
-- the signer e-mail must be the customer's (account e-mail or the customer card e-mail); otherwise nothing is
-- accepted and the reason is kept for review. Exactly once: one immutable row per request in
-- pro_esign_acceptances + a deterministic actionId per request in the writer (its own idempotency receipt);
-- the writers keep their own history/audit. pro_esign_event_apply is re-created with the same body as 6B plus
-- that call (errors inside it never block storing the signature).
begin;

create table if not exists public.pro_esign_acceptances(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 request_id uuid not null,
 document_kind text not null check(document_kind in('contract','quote','work_change')),
 document_id uuid not null,
 outcome text not null check(outcome in('accepted','already_accepted','review')),
 reason text check(reason is null or length(reason) between 1 and 120),
 action_id uuid not null,
 writer_result jsonb check(writer_result is null or octet_length(writer_result::text)<=65536),
 created_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,request_id),
 foreign key(owner_id,request_id) references public.pro_esign_requests(owner_id,id) on delete cascade,
 check((outcome='review')=(reason is not null))
);
create or replace function public.pro_esign_acceptance_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'E-signature acceptances are immutable' using errcode='23514';end $$;
drop trigger if exists pro_esign_acceptance_immutable on public.pro_esign_acceptances;
create trigger pro_esign_acceptance_immutable before update on public.pro_esign_acceptances for each row execute function public.pro_esign_acceptance_immutable();

-- plpgsql (late binding): the account e-mail lives in auth.users; profiles.email and the customer card are fallbacks.
create or replace function public.pro_esign_signer_is_customer(p_signer text,p_user uuid,p_owner uuid,p_client text) returns boolean
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare signer text:=lower(btrim(coalesce(p_signer,'')));
begin
 if signer='' then return false;end if;
 if p_user is not null and (exists(select 1 from auth.users u where u.id=p_user and lower(btrim(coalesce(u.email,'')))=signer)
  or exists(select 1 from public.profiles pr where pr.id=p_user and lower(btrim(coalesce(pr.email,'')))=signer)) then return true;end if;
 return p_client is not null and exists(select 1 from public.pro_clients c where c.user_id=p_owner and c.id=p_client and lower(btrim(coalesce(c.email,'')))=signer);
end $$;

create or replace function public.pro_esign_apply_acceptance(p_owner uuid,p_request uuid) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare r public.pro_esign_requests;prior public.pro_esign_acceptances;aid uuid;outcome text;reason text;res jsonb;current_hash text;
 c public.pro_contracts;v public.pro_contract_versions;w public.pro_work;req uuid;pub public.pro_private_estimate_publications;st public.pro_private_estimate_publication_states;ch public.pro_work_changes;input jsonb;
begin
 select * into r from public.pro_esign_requests where owner_id=p_owner and id=p_request;
 if not found then raise exception 'Unknown request' using errcode='P0002';end if;
 select * into prior from public.pro_esign_acceptances where owner_id=p_owner and request_id=p_request;
 if found then return jsonb_build_object('outcome',prior.outcome,'reason',prior.reason,'duplicate',true);end if;
 if r.status<>'signed' then raise exception 'Request not signed' using errcode='22023';end if;
 aid:=md5('ccr-esign-acceptance:'||r.id::text)::uuid;
 begin current_hash:=public.pro_esign_document(p_owner,r.document_kind,r.document_id)->>'contentHash';
 exception when others then current_hash:=null;end;
 if current_hash is null then outcome:='review';reason:='document_not_signable';
 elsif current_hash<>r.document_hash then outcome:='review';reason:='document_changed';
 elsif r.document_kind='contract' then
  select * into c from public.pro_contracts where owner_id=p_owner and id=r.document_id;
  select * into v from public.pro_contract_versions where owner_id=p_owner and contract_id=c.id and version=c.latest_version;
  select * into w from public.pro_work where user_id=p_owner and id=c.work_id;
  if c.status='accepted' then outcome:='already_accepted';
  elsif not public.pro_esign_signer_is_customer(r.signer_email,v.recipient_id,p_owner,w."clientId") then outcome:='review';reason:='signer_not_customer';
  else
   select ar.id into req from public.pro_appointment_requests ar where ar.owner_id=p_owner and ar.work_id=c.work_id and ar.client_user_id=v.recipient_id and ar.status in('confirmed','completed') order by ar.updated_at desc,ar.id desc limit 1;
   if req is null then outcome:='review';reason:='no_customer_link';
   else
    begin
     res:=public.pro_contracts_client_mutate(v.recipient_id,jsonb_build_object('action','accept','actionId',aid,'requestId',req,'contractId',c.id,'version',v.version,'contentHash',v.content_hash,'typedName',left(r.signer_name,160)));
     outcome:='accepted';
    exception when others then outcome:='review';reason:='writer_refused_'||sqlstate;end;
   end if;
  end if;
 elsif r.document_kind='quote' then
  select * into pub from public.pro_private_estimate_publications where owner_id=p_owner and id=r.document_id;
  select * into st from public.pro_private_estimate_publication_states where publication_id=pub.id;
  if st.status='accepted' then outcome:='already_accepted';
  elsif st.recipient_id is null or st.status not in('shared','changes_requested') then outcome:='review';reason:='no_customer_link';
  elsif not public.pro_esign_signer_is_customer(r.signer_email,st.recipient_id,p_owner,pub.client_id) then outcome:='review';reason:='signer_not_customer';
  else
   input:=jsonb_build_object('action','accept','actionId',aid,'contentHash',pub.content_hash,'publicationId',pub.id,'revision',st.revision);
   begin
    res:=public.pro_private_estimate_publication_mutate(st.recipient_id,input,encode(sha256(convert_to(input::text,'UTF8')),'hex'));
    outcome:='accepted';
   exception when others then outcome:='review';reason:='writer_refused_'||sqlstate;end;
  end if;
 else
  select * into ch from public.pro_work_changes where owner_id=p_owner and id=r.document_id;
  if ch.status='accepted' then outcome:='already_accepted';
  else
   begin
    res:=public.pro_work_changes_mutate(p_owner,jsonb_build_object('action','record_acceptance','id',ch.id,'actionId',aid,'revision',ch.revision,
     'note',left(case when r.language='en' then 'Electronically signed by ' else 'Firmado electrónicamente por ' end||r.signer_name||' <'||r.signer_email||'> · '||case when r.language='en' then 'envelope ' else 'sobre ' end||coalesce(r.envelope_id,'-')||' · '||to_char(coalesce(r.completed_at,now()) at time zone 'America/Costa_Rica','YYYY-MM-DD HH24:MI'),500)));
    outcome:='accepted';
   exception when others then outcome:='review';reason:='writer_refused_'||sqlstate;end;
  end if;
 end if;
 insert into public.pro_esign_acceptances(owner_id,request_id,document_kind,document_id,outcome,reason,action_id,writer_result)
 values(p_owner,r.id,r.document_kind,r.document_id,outcome,reason,aid,res);
 return jsonb_build_object('outcome',outcome,'reason',reason,'duplicate',false);
end $$;

-- Owner view of the automatic acceptances of one document (shown next to its signature requests).
create or replace function public.pro_esign_acceptances_read(p_actor uuid,p_kind text,p_id uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 return coalesce((select jsonb_agg(jsonb_build_object('requestId',a.request_id,'outcome',a.outcome,'reason',a.reason,'at',a.created_at) order by a.created_at desc)
  from public.pro_esign_acceptances a where a.owner_id=p_actor and a.document_kind=p_kind and a.document_id=p_id),'[]');
end $$;

create or replace function public.pro_esign_event_apply(p_webhook uuid,p_pdf bytea default null,p_certificate bytea default null) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare wh public.pro_integration_webhooks;r public.pro_esign_requests;target text;ps text;acc jsonb;
begin
 select * into wh from public.pro_integration_webhooks where id=p_webhook and provider='esign' for update;
 if not found then raise exception 'Unknown webhook' using errcode='22023';end if;
 if wh.status in('processed','ignored') then return jsonb_build_object('status',wh.status,'duplicate',true,'review',wh.last_error);end if;
 select * into r from public.pro_esign_requests where mode=wh.mode and envelope_id=wh.payload->>'envelopeId' for update;
 if not found then
  update public.pro_integration_webhooks set status='ignored',processed_at=now(),last_error='unknown_envelope' where id=wh.id;
  return jsonb_build_object('status','ignored','duplicate',false,'review','unknown_envelope');
 end if;
 if wh.owner_id is null then update public.pro_integration_webhooks set owner_id=r.owner_id where id=wh.id;end if;
 ps:=wh.payload->>'status';
 target:=case ps when 'delivered' then 'viewed' when 'completed' then 'signed' when 'declined' then 'declined' when 'voided' then 'cancelled' when 'expired' then 'expired' when 'sent' then 'sent' else null end;
 if target is null then
  update public.pro_integration_webhooks set status='ignored',processed_at=now(),last_error='unknown_status' where id=wh.id;
  return jsonb_build_object('status','ignored','duplicate',false,'review','unknown_status');
 end if;
 if r.status=target then
  update public.pro_integration_webhooks set status='processed',processed_at=now(),last_error='already_applied' where id=wh.id;
  return jsonb_build_object('status','processed','duplicate',true,'review',null,'request',r.id);
 end if;
 if not public.pro_esign_transition_ok(r.status,target) then
  update public.pro_integration_webhooks set status='ignored',processed_at=now(),last_error=left('out_of_order_'||r.status||'_'||target,300) where id=wh.id;
  return jsonb_build_object('status','ignored','duplicate',false,'review','out_of_order','request',r.id);
 end if;
 if target='signed' then
  if p_pdf is null or p_certificate is null then raise exception 'Completed envelope without documents' using errcode='22023',hint='pro_esign_documents_missing';end if;
  insert into public.pro_esign_artifacts(owner_id,request_id,kind,content,sha256) values
   (r.owner_id,r.id,'signed_pdf',p_pdf,encode(sha256(p_pdf),'hex')),(r.owner_id,r.id,'certificate',p_certificate,encode(sha256(p_certificate),'hex'));
 end if;
 update public.pro_esign_requests set status=target,
  viewed_at=case when target='viewed' then coalesce(viewed_at,now()) else viewed_at end,
  completed_at=case when target in('signed','declined','expired','cancelled') then now() else completed_at end,
  decline_reason=case when target='declined' then left(coalesce(nullif(btrim(wh.payload->>'reason'),''),'Sin motivo'),500) else decline_reason end,
  revision=revision+1,updated_at=now() where owner_id=r.owner_id and id=r.id returning * into r;
 perform public.pro_esign_log(r.owner_id,r.id,target,'provider',wh.id,jsonb_build_object('event',wh.event_id,'providerStatus',ps));
 -- Round 6C: a signed envelope updates the acceptance of the document through its own writer (exactly once).
 if target='signed' then
  begin acc:=public.pro_esign_apply_acceptance(r.owner_id,r.id);
  exception when others then acc:=jsonb_build_object('outcome','review','reason','error_'||sqlstate);end;
 end if;
 update public.pro_integration_webhooks set status='processed',processed_at=now() where id=wh.id;
 return jsonb_build_object('status','processed','duplicate',false,'review',null,'request',r.id,'requestStatus',r.status)||case when acc is null then '{}'::jsonb else jsonb_build_object('acceptance',acc) end;
end $$;


alter table public.pro_esign_acceptances enable row level security;
revoke all on public.pro_esign_acceptances from public,anon,authenticated,service_role;
grant select,insert on public.pro_esign_acceptances to service_role;
do $$declare f regprocedure;begin
 for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('pro_esign_apply_acceptance','pro_esign_acceptances_read','pro_esign_signer_is_customer','pro_esign_event_apply','pro_esign_acceptance_immutable') loop
  execute format('revoke all on function %s from public,anon,authenticated',f);
  if f::text not like 'pro_esign_acceptance_immutable(%' then execute format('grant execute on function %s to service_role',f);end if;
 end loop;end $$;
notify pgrst,'reload schema';
commit;

-- ===== calendar-autosync-local.sql =====
-- LOCAL PRO ONLY. Round 6C (2026-11-13): follow-up of Round 6B — automatic calendar sync on a schedule.
-- The owner chooses an interval per connected calendar (off by default; 15/30/60/120 minutes). While the Pro
-- app is open, an in-app ticker asks the server to run due syncs; pro_calendar_autosync_claim decides
-- atomically (row lock + next_run_at) so two tabs or two devices never run the same window twice. Each run is
-- an immutable row (started → ok/error with the counts). Same sync code as «Sincronizar» (mock by default).
begin;

create table if not exists public.pro_calendar_autosync(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 provider text not null check(provider in('google','microsoft')),
 interval_minutes integer not null default 0 check(interval_minutes in(0,15,30,60,120)),
 next_run_at timestamptz,last_run_at timestamptz,
 revision integer not null default 1 check(revision>0),
 updated_at timestamptz not null default now(),
 primary key(owner_id,provider),
 check((interval_minutes=0)=(next_run_at is null))
);
create table if not exists public.pro_calendar_autosync_runs(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 run_id uuid not null,provider text not null check(provider in('google','microsoft')),
 status text not null default 'running' check(status in('running','ok','error')),
 summary jsonb check(summary is null or (jsonb_typeof(summary)='object' and octet_length(summary::text)<=2048)),
 started_at timestamptz not null default clock_timestamp(),finished_at timestamptz,
 primary key(owner_id,run_id),check((status='running')=(finished_at is null))
);
create index if not exists pro_calendar_autosync_runs_recent on public.pro_calendar_autosync_runs(owner_id,started_at desc);
create table if not exists public.pro_calendar_autosync_actions(
 owner_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 input jsonb not null,result jsonb not null,created_at timestamptz not null default now(),primary key(owner_id,action_id)
);
create or replace function public.pro_calendar_autosync_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if tg_table_name='pro_calendar_autosync_actions' or old.status<>'running' or (new.owner_id,new.run_id,new.provider,new.started_at) is distinct from (old.owner_id,old.run_id,old.provider,old.started_at) then
  raise exception 'Auto-sync history is immutable' using errcode='23514';end if;
 return new;
end $$;
drop trigger if exists pro_calendar_autosync_runs_guard on public.pro_calendar_autosync_runs;
create trigger pro_calendar_autosync_runs_guard before update on public.pro_calendar_autosync_runs for each row execute function public.pro_calendar_autosync_guard();
drop trigger if exists pro_calendar_autosync_actions_guard on public.pro_calendar_autosync_actions;
create trigger pro_calendar_autosync_actions_guard before update on public.pro_calendar_autosync_actions for each row execute function public.pro_calendar_autosync_guard();

create or replace function public.pro_calendar_autosync_read(p_actor uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 return jsonb_build_object(
  'settings',(select coalesce(jsonb_agg(jsonb_build_object('provider',p.provider,'intervalMinutes',coalesce(s.interval_minutes,0),'nextRunAt',s.next_run_at,'lastRunAt',s.last_run_at,'revision',coalesce(s.revision,0)) order by p.provider),'[]')
   from (values('google'),('microsoft')) p(provider) left join public.pro_calendar_autosync s on s.owner_id=p_actor and s.provider=p.provider),
  'runs',coalesce((select jsonb_agg(jsonb_build_object('runId',r.run_id,'provider',r.provider,'status',r.status,'summary',r.summary,'startedAt',r.started_at,'finishedAt',r.finished_at) order by r.started_at desc)
   from (select * from public.pro_calendar_autosync_runs where owner_id=p_actor order by started_at desc limit 10) r),'[]'));
end $$;
create or replace function public.pro_calendar_autosync_set(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;prov text:=p_input->>'provider';mins integer;receipt public.pro_calendar_autosync_actions;s public.pro_calendar_autosync;result jsonb;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input)<>'object' or prov not in('google','microsoft') or jsonb_typeof(p_input->'intervalMinutes')<>'number' or jsonb_typeof(p_input->'revision')<>'number' then raise exception 'Invalid auto-sync' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;exception when others then raise exception 'Invalid action id' using errcode='22023';end;
 mins:=(p_input->>'intervalMinutes')::integer;if aid is null or mins not in(0,15,30,60,120) then raise exception 'Invalid auto-sync' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-calendar-autosync:'||p_actor::text,0));
 select * into receipt from public.pro_calendar_autosync_actions where owner_id=p_actor and action_id=aid;
 if found then if receipt.input<>p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;return receipt.result;end if;
 select * into s from public.pro_calendar_autosync where owner_id=p_actor and provider=prov for update;
 if (p_input->>'revision')::integer is distinct from coalesce(s.revision,0) then raise exception 'Auto-sync changed' using errcode='40001';end if;
 insert into public.pro_calendar_autosync(owner_id,provider,interval_minutes,next_run_at) values(p_actor,prov,mins,case when mins>0 then now() end)
 on conflict(owner_id,provider) do update set interval_minutes=excluded.interval_minutes,next_run_at=excluded.next_run_at,revision=pro_calendar_autosync.revision+1,updated_at=now();
 result:=public.pro_calendar_autosync_read(p_actor);
 insert into public.pro_calendar_autosync_actions(owner_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;
-- Atomic claim of one due window: true only for the first caller; moves next_run_at forward.
create or replace function public.pro_calendar_autosync_claim(p_actor uuid,p_provider text,p_run uuid) returns boolean
language plpgsql security invoker set search_path=public,pg_temp as $$
declare s public.pro_calendar_autosync;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into s from public.pro_calendar_autosync where owner_id=p_actor and provider=p_provider for update;
 if not found or s.interval_minutes=0 or s.next_run_at>now() then return false;end if;
 if exists(select 1 from public.pro_calendar_autosync_runs where owner_id=p_actor and run_id=p_run) then return false;end if;
 update public.pro_calendar_autosync set next_run_at=now()+make_interval(mins=>s.interval_minutes),last_run_at=now() where owner_id=p_actor and provider=p_provider;
 insert into public.pro_calendar_autosync_runs(owner_id,run_id,provider) values(p_actor,p_run,p_provider);
 return true;
end $$;
create or replace function public.pro_calendar_autosync_finish(p_actor uuid,p_run uuid,p_ok boolean,p_summary jsonb) returns void
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 update public.pro_calendar_autosync_runs set status=case when p_ok then 'ok' else 'error' end,summary=p_summary,finished_at=clock_timestamp()
  where owner_id=p_actor and run_id=p_run and status='running';
end $$;

do $$declare n text;begin foreach n in array array['pro_calendar_autosync','pro_calendar_autosync_runs','pro_calendar_autosync_actions'] loop
 execute format('alter table public.%I enable row level security',n);execute format('revoke all on public.%I from public,anon,authenticated,service_role',n);execute format('grant select,insert,update on public.%I to service_role',n);
end loop;end $$;
do $$declare f regprocedure;begin
 for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'pro\_calendar\_autosync\_%' loop
  execute format('revoke all on function %s from public,anon,authenticated',f);
  if f::text not like 'pro_calendar_autosync_guard(%' then execute format('grant execute on function %s to service_role',f);end if;
 end loop;end $$;
notify pgrst,'reload schema';
commit;

-- ===== marketing-providers-local.sql =====
-- LOCAL PRO ONLY. Round 6D (2026-11-13): five more providers in the Round 6A–6C integration framework, all
-- MOCK by default and never automatic in production (same rules: sandbox only with every env var, production
-- only with the typed confirmation AND PRO_INTEGRATIONS_ALLOW_PRODUCTION=1):
--   marketing_email  email campaigns and automations (Brevo transactional API adapter, inactive)
--   meta_ads         Meta Marketing API cost import (documented stub, inactive)
--   google_ads       Google Ads API cost import (documented stub, inactive)
--   product_clipper  public product page reader for «Agregar desde enlace» (Open Graph / schema.org; inactive)
--   site_domain      custom domain for the professional website (Cloudflare for SaaS custom hostnames; inactive)
-- Only the provider whitelist changes; pro_integration_read/mutate already read pro_integration_provider_ids().
begin;
create or replace function public.pro_integration_provider_ids() returns text[]
language sql immutable security invoker set search_path=public,pg_temp as $$
 select array['hacienda','tilopay','esign','google','microsoft','quickbooks','ai','transcription','marketing_email','meta_ads','google_ads','product_clipper','site_domain']::text[] $$;
do $$declare t text;begin foreach t in array array['pro_integration_connections','pro_integration_requests','pro_integration_webhooks'] loop
 execute format('alter table public.%I drop constraint if exists %I',t,t||'_provider_check');
 execute format('alter table public.%I add constraint %I check(provider = any(public.pro_integration_provider_ids()))',t,t||'_provider_check');
end loop;end $$;
revoke all on function public.pro_integration_provider_ids() from public,anon,authenticated;
grant execute on function public.pro_integration_provider_ids() to service_role;
notify pgrst,'reload schema';
commit;

-- ===== email-marketing-local.sql =====
-- LOCAL PRO ONLY. Round 6D (2026-11-13): email campaigns and automations for professionals (row 71).
-- * Audience = the professional's own contacts (Pro clients / leads) WITH explicit marketing consent. Consent is
--   recorded with its text, source, evidence and date (immutable events). Revocation and every unsubscribe put
--   the address on a per-owner suppression list (SHA-256 of the lowercase email; insert-only).
-- * The DATABASE refuses any campaign/automation message to a contact that is not «granted» or is suppressed
--   (trigger pro_mkt_message_guard, 42501 pro_mkt_no_consent): no code path can send to non-consenting people.
-- * Test sends go only to the owner's own account email (outbox viewer). In mock mode every message is stored
--   as «simulado» (CHECK): nothing leaves the machine. Real delivery needs the marketing_email provider (inactive).
-- * Automations (follow-up after a quote was shared, review request after a completed job) only create DRAFTS in
--   «pending_approval»; nothing is queued until the owner approves each draft.
-- * Every unsubscribe link carries a random token whose SHA-256 is stored; the public page only needs the token.
-- * Post-security fixes (2026-11-13), Ley 8968 DOUBLE OPT-IN: a site-form tick only creates a «pending» contact and a
--   confirmation email (mock adapter: stored as «simulado», never sent) carrying a single-use token whose SHA-256 is
--   stored. Only the recipient's confirmation makes the contact «granted»; the CHECK pro_mkt_contacts_double_optin and
--   the message guard refuse any campaign/automation to a site-form contact that never confirmed. Owner-recorded
--   consent with evidence is unchanged. An unsubscribed address gets nothing (same public answer as anyone).
-- Tables: RLS on, service_role only; history/events/messages/suppressions immutable; functions security invoker.
begin;
create or replace function public.pro_mkt_email_hash(p_email text) returns text
language sql immutable security invoker set search_path=public,pg_temp as $$ select encode(sha256(convert_to(lower(btrim(p_email)),'UTF8')),'hex') $$;
create table if not exists public.pro_mkt_contacts(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 id uuid not null,
 email text not null check(length(email) between 3 and 254 and email~'^[^@\s]+@[^@\s]+\.[^@\s]+$' and email=lower(email)),
 email_hash text generated always as (public.pro_mkt_email_hash(email)) stored,
 name text not null check(length(btrim(name)) between 1 and 160),
 client_id text check(client_id is null or length(client_id) between 1 and 160),
 lead_id uuid,
 consent text not null default 'none' check(consent in('granted','revoked','none')),
 consent_source text check(consent_source is null or consent_source in('site_form','owner_recorded')),
 consent_text text check(consent_text is null or length(consent_text) between 20 and 1000),
 consent_at timestamptz,revoked_at timestamptz,
 revision integer not null default 1 check(revision>0),
 created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,id),unique(owner_id,email),
 check(consent<>'granted' or (consent_source is not null and consent_text is not null and consent_at is not null)),
 check(consent<>'revoked' or revoked_at is not null)
);
create table if not exists public.pro_mkt_consent_events(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,contact_id uuid not null,
 event text not null check(event in('granted','revoked','unsubscribed')),
 source text not null check(source in('site_form','owner_recorded','unsubscribe_link','owner_revoked')),
 consent_text text check(consent_text is null or length(consent_text)<=1000),
 evidence jsonb not null default '{}' check(jsonb_typeof(evidence)='object' and octet_length(evidence::text)<=2048),
 at timestamptz not null default clock_timestamp(),primary key(owner_id,id),
 foreign key(owner_id,contact_id) references public.pro_mkt_contacts(owner_id,id) on delete cascade
);
create table if not exists public.pro_mkt_suppressions(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 email_hash text not null check(email_hash~'^[a-f0-9]{64}$'),
 reason text not null check(reason in('unsubscribed','owner','bounced','complaint')),
 at timestamptz not null default clock_timestamp(),primary key(owner_id,email_hash)
);
create table if not exists public.pro_mkt_unsubscribe_tokens(
 token_hash text primary key check(token_hash~'^[a-f0-9]{64}$'),
 owner_id uuid not null references public.profiles(id) on delete cascade,contact_id uuid not null,
 created_at timestamptz not null default clock_timestamp(),used_at timestamptz,
 foreign key(owner_id,contact_id) references public.pro_mkt_contacts(owner_id,id) on delete cascade
);
create table if not exists public.pro_mkt_templates(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,
 name text not null check(length(btrim(name)) between 1 and 120),
 subject text not null check(length(btrim(subject)) between 1 and 160),
 body text not null check(length(btrim(body)) between 1 and 8000),
 archived boolean not null default false,revision integer not null default 1 check(revision>0),
 created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),primary key(owner_id,id)
);
create table if not exists public.pro_mkt_campaigns(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,
 name text not null check(length(btrim(name)) between 1 and 120),
 subject text not null check(length(btrim(subject)) between 1 and 160),
 body text not null check(length(btrim(body)) between 1 and 8000),
 segment text not null default 'all' check(segment in('all','clients','leads')),
 status text not null default 'draft' check(status in('draft','scheduled','sent','cancelled')),
 scheduled_at timestamptz,sent_at timestamptz,recipients integer check(recipients is null or recipients>=0),
 mode text check(mode is null or mode in('mock','sandbox','production')),
 revision integer not null default 1 check(revision>0),
 created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),primary key(owner_id,id),
 check((status='scheduled')=(scheduled_at is not null and sent_at is null) or status<>'scheduled'),
 check((status='sent')=(sent_at is not null and recipients is not null and mode is not null))
);
create table if not exists public.pro_mkt_automations(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 kind text not null check(kind in('quote_followup','review_request')),
 enabled boolean not null default false,delay_days integer not null default 3 check(delay_days between 0 and 60),
 subject text not null check(length(btrim(subject)) between 1 and 160),
 body text not null check(length(btrim(body)) between 1 and 8000),
 revision integer not null default 1 check(revision>0),updated_at timestamptz not null default clock_timestamp(),primary key(owner_id,kind)
);
create table if not exists public.pro_mkt_automation_drafts(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,
 kind text not null check(kind in('quote_followup','review_request')),
 ref_kind text not null check(ref_kind in('estimate_publication','work')),ref_id text not null check(length(ref_id) between 1 and 160),
 ref_label text not null check(length(ref_label) between 1 and 200),
 contact_id uuid not null,subject text not null,body text not null,
 status text not null default 'pending_approval' check(status in('pending_approval','approved','rejected')),
 created_at timestamptz not null default clock_timestamp(),decided_at timestamptz,message_id uuid,
 primary key(owner_id,id),unique(owner_id,kind,ref_id),
 foreign key(owner_id,contact_id) references public.pro_mkt_contacts(owner_id,id) on delete cascade,
 check((status='pending_approval')=(decided_at is null)),check((status='approved')=(message_id is not null))
);
create table if not exists public.pro_mkt_messages(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,
 kind text not null check(kind in('test','campaign','automation')),
 campaign_id uuid,draft_id uuid,contact_id uuid,
 to_email text not null check(length(to_email) between 3 and 254),
 subject text not null check(length(subject) between 1 and 200),body text not null check(length(body) between 1 and 12000),
 token_hash text check(token_hash is null or token_hash~'^[a-f0-9]{64}$'),
 mode text not null check(mode in('mock','sandbox','production')),
 delivery text not null check(delivery in('simulado','queued','sent','failed')),
 created_at timestamptz not null default clock_timestamp(),primary key(owner_id,id),
 check(mode<>'mock' or delivery='simulado'),
 check(kind='test' or (contact_id is not null and token_hash is not null)),
 check((kind='campaign')=(campaign_id is not null)),check((kind='automation')=(draft_id is not null))
);
create index if not exists pro_mkt_messages_recent on public.pro_mkt_messages(owner_id,created_at desc);
create table if not exists public.pro_mkt_actions(
 owner_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 input jsonb not null,result jsonb not null,created_at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id)
);
create table if not exists public.pro_mkt_history(
 owner_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 action text not null,entity text not null,entity_id text not null,snapshot jsonb not null check(octet_length(snapshot::text)<=32768),
 at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id)
);


-- Post-security fixes: double opt-in columns and rules (idempotent for databases that already have the tables).
alter table public.pro_mkt_contacts add column if not exists confirmation_requested_at timestamptz,add column if not exists confirmed_at timestamptz;
alter table public.pro_mkt_contacts drop constraint if exists pro_mkt_contacts_consent_check;
alter table public.pro_mkt_contacts add constraint pro_mkt_contacts_consent_check check(consent in('granted','pending','revoked','none'));
alter table public.pro_mkt_contacts drop constraint if exists pro_mkt_contacts_double_optin;
alter table public.pro_mkt_contacts add constraint pro_mkt_contacts_double_optin check(consent<>'granted' or consent_source is distinct from 'site_form' or confirmed_at is not null);
alter table public.pro_mkt_contacts drop constraint if exists pro_mkt_contacts_pending;
alter table public.pro_mkt_contacts add constraint pro_mkt_contacts_pending check(consent<>'pending' or (consent_source='site_form' and consent_text is not null and confirmation_requested_at is not null and confirmed_at is null));
alter table public.pro_mkt_consent_events drop constraint if exists pro_mkt_consent_events_event_check;
alter table public.pro_mkt_consent_events add constraint pro_mkt_consent_events_event_check check(event in('granted','revoked','unsubscribed','requested','confirmed'));
alter table public.pro_mkt_consent_events drop constraint if exists pro_mkt_consent_events_source_check;
alter table public.pro_mkt_consent_events add constraint pro_mkt_consent_events_source_check check(source in('site_form','owner_recorded','unsubscribe_link','owner_revoked','confirmation_link'));
-- The confirmation email of the MOCK adapter (never sent) with its single-use token (only the SHA-256 is the key).
-- Owners never read this table (no reader exposes it): an owner cannot confirm on the recipient's behalf.
create table if not exists public.pro_mkt_confirmations(
 token_hash text primary key check(token_hash~'^[a-f0-9]{64}$'),
 owner_id uuid not null references public.profiles(id) on delete cascade,contact_id uuid not null,
 to_email text not null check(length(to_email) between 3 and 254),
 subject text not null check(length(subject) between 1 and 200),body text not null check(length(body) between 1 and 4000),
 mode text not null default 'mock' check(mode='mock'),delivery text not null default 'simulado' check(delivery='simulado'),
 created_at timestamptz not null default clock_timestamp(),expires_at timestamptz not null,used_at timestamptz,
 check(expires_at>created_at),
 foreign key(owner_id,contact_id) references public.pro_mkt_contacts(owner_id,id) on delete cascade
);
create index if not exists pro_mkt_confirmations_contact on public.pro_mkt_confirmations(owner_id,contact_id,created_at desc);

-- ---------------------------------------------------------------- guards
create or replace function public.pro_mkt_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Marketing history, consent events, suppressions and messages are immutable' using errcode='23514';end $$;
do $$declare t text;begin foreach t in array array['pro_mkt_consent_events','pro_mkt_suppressions','pro_mkt_messages','pro_mkt_actions','pro_mkt_history'] loop
 execute format('drop trigger if exists %I on public.%I',t||'_immutable',t);
 execute format('create trigger %I before update on public.%I for each row execute function public.pro_mkt_immutable()',t||'_immutable',t);
end loop;end $$;
-- The consent rule lives in the database: a campaign or automation message needs a granted, non-suppressed contact.
create or replace function public.pro_mkt_message_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
declare c public.pro_mkt_contacts;
begin
 if new.kind='test' then
  if lower(new.to_email) is distinct from (select lower(email) from public.profiles where id=new.owner_id) then
   raise exception 'Test sends only go to the owner''s own email' using errcode='42501',hint='pro_mkt_test_owner_only';end if;
  return new;end if;
 select * into c from public.pro_mkt_contacts where owner_id=new.owner_id and id=new.contact_id;
 if not found or c.consent<>'granted' or c.email<>lower(new.to_email)
    or (c.consent_source='site_form' and c.confirmed_at is null) -- double opt-in: a site-form contact must have confirmed
    or exists(select 1 from public.pro_mkt_suppressions s where s.owner_id=new.owner_id and s.email_hash=public.pro_mkt_email_hash(new.to_email)) then
  raise exception 'No marketing consent for this recipient' using errcode='42501',hint='pro_mkt_no_consent';end if;
 return new;
end $$;
create or replace function public.pro_mkt_confirmation_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if (to_jsonb(new)-'used_at') is distinct from (to_jsonb(old)-'used_at') or old.used_at is not null then
  raise exception 'A confirmation is immutable and single-use' using errcode='23514';end if;
 return new;
end $$;
drop trigger if exists pro_mkt_confirmation_guard on public.pro_mkt_confirmations;
create trigger pro_mkt_confirmation_guard before update on public.pro_mkt_confirmations for each row execute function public.pro_mkt_confirmation_guard();
drop trigger if exists pro_mkt_message_guard on public.pro_mkt_messages;
create trigger pro_mkt_message_guard before insert on public.pro_mkt_messages for each row execute function public.pro_mkt_message_guard();
create or replace function public.pro_mkt_draft_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if (new.owner_id,new.id,new.kind,new.ref_kind,new.ref_id,new.contact_id,new.subject,new.body,new.created_at) is distinct from (old.owner_id,old.id,old.kind,old.ref_kind,old.ref_id,old.contact_id,old.subject,old.body,old.created_at) then
  raise exception 'An automation draft is immutable' using errcode='23514';end if;
 if old.status<>'pending_approval' and (new.status,new.decided_at,new.message_id) is distinct from (old.status,old.decided_at,old.message_id) then
  raise exception 'The approval decision is recorded once' using errcode='23514';end if;
 return new;
end $$;
drop trigger if exists pro_mkt_draft_guard on public.pro_mkt_automation_drafts;
create trigger pro_mkt_draft_guard before update on public.pro_mkt_automation_drafts for each row execute function public.pro_mkt_draft_guard();

-- ---------------------------------------------------------------- helpers
create or replace function public.pro_mkt_owner(p_actor uuid) returns void
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;end $$;
create or replace function public.pro_mkt_business(p_owner uuid) returns text
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce(nullif(btrim(p.business_name),''),nullif(btrim(f.full_name),''),'ContrataCR') from public.profiles f left join public.professionals p on p.profile_id=f.id where f.id=p_owner $$;
create or replace function public.pro_mkt_contact_json(c public.pro_mkt_contacts) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',c.id,'email',c.email,'name',c.name,'clientId',c.client_id,'leadId',c.lead_id,'consent',c.consent,'consentSource',c.consent_source,'consentText',c.consent_text,'consentAt',c.consent_at,'revokedAt',c.revoked_at,'confirmationRequestedAt',c.confirmation_requested_at,'confirmedAt',c.confirmed_at,
  'suppressed',exists(select 1 from public.pro_mkt_suppressions s where s.owner_id=c.owner_id and s.email_hash=c.email_hash),'revision',c.revision,'createdAt',c.created_at) $$;
/** Records explicit consent (site form or the owner attesting consent obtained). A suppressed address stays suppressed. */
create or replace function public.pro_mkt_grant(p_owner uuid,p_email text,p_name text,p_source text,p_text text,p_evidence jsonb,p_client text,p_lead uuid) returns public.pro_mkt_contacts
language plpgsql security invoker set search_path=public,pg_temp as $$
declare c public.pro_mkt_contacts;e text:=lower(btrim(p_email));
begin
 -- Double opt-in: consent from the site form is never granted here (pro_mkt_request_confirmation + pro_mkt_confirm).
 if p_source is distinct from 'owner_recorded' then raise exception 'Only owner-recorded consent is granted directly' using errcode='22023';end if;
if exists(select 1 from public.pro_mkt_suppressions where owner_id=p_owner and email_hash=public.pro_mkt_email_hash(e)) then
  raise exception 'This address unsubscribed; it cannot be added again from here' using errcode='42501',hint='pro_mkt_suppressed';end if;
 insert into public.pro_mkt_contacts(owner_id,id,email,name,client_id,lead_id,consent,consent_source,consent_text,consent_at)
 values(p_owner,gen_random_uuid(),e,btrim(p_name),p_client,p_lead,'granted',p_source,p_text,clock_timestamp())
 on conflict(owner_id,email) do update set name=excluded.name,client_id=coalesce(pro_mkt_contacts.client_id,excluded.client_id),lead_id=coalesce(pro_mkt_contacts.lead_id,excluded.lead_id),
  consent='granted',consent_source=excluded.consent_source,consent_text=excluded.consent_text,consent_at=excluded.consent_at,revoked_at=null,revision=pro_mkt_contacts.revision+1,updated_at=clock_timestamp()
 returning * into c;
 insert into public.pro_mkt_consent_events(owner_id,id,contact_id,event,source,consent_text,evidence) values(p_owner,gen_random_uuid(),c.id,'granted',p_source,p_text,coalesce(p_evidence,'{}'));
 return c;
end $$;
create or replace function public.pro_mkt_suppress(p_owner uuid,p_contact uuid,p_reason text,p_source text) returns void
language plpgsql security invoker set search_path=public,pg_temp as $$
declare c public.pro_mkt_contacts;
begin
 select * into c from public.pro_mkt_contacts where owner_id=p_owner and id=p_contact for update;if not found then raise exception 'Contact unavailable' using errcode='P0002';end if;
 insert into public.pro_mkt_suppressions(owner_id,email_hash,reason) values(p_owner,c.email_hash,p_reason) on conflict do nothing;
 if c.consent<>'revoked' then
  update public.pro_mkt_contacts set consent='revoked',revoked_at=clock_timestamp(),revision=revision+1,updated_at=clock_timestamp() where owner_id=p_owner and id=p_contact;
  insert into public.pro_mkt_consent_events(owner_id,id,contact_id,event,source) values(p_owner,gen_random_uuid(),p_contact,case when p_reason='unsubscribed' then 'unsubscribed' else 'revoked' end,p_source);
 end if;
end $$;
create or replace function public.pro_mkt_render(p_owner uuid,p_text text,p_name text,p_link text) returns text
language sql stable security invoker set search_path=public,pg_temp as $$
 select replace(replace(replace(p_text,'{{nombre}}',split_part(btrim(coalesce(p_name,'')),' ',1)),'{{negocio}}',public.pro_mkt_business(p_owner)),'{{enlace}}',coalesce(p_link,'')) $$;
create or replace function public.pro_mkt_base_ok(p_base text) returns text
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
begin if p_base is null or p_base!~'^https?://[A-Za-z0-9.:-]{3,120}$' then raise exception 'Invalid base URL' using errcode='22023';end if;return p_base;end $$;
/** One outbox message for one consenting contact, with its own unsubscribe token. The guard trigger re-checks consent. */
create or replace function public.pro_mkt_enqueue(p_owner uuid,p_contact uuid,p_kind text,p_campaign uuid,p_draft uuid,p_subject text,p_body text,p_mode text,p_base text,p_link text default null) returns uuid
language plpgsql security invoker set search_path=public,pg_temp as $$
declare c public.pro_mkt_contacts;token text:=replace(gen_random_uuid()::text||gen_random_uuid()::text,'-','');mid uuid:=gen_random_uuid();url text;footer text;
begin
 select * into c from public.pro_mkt_contacts where owner_id=p_owner and id=p_contact;
 url:=public.pro_mkt_base_ok(p_base)||'/baja-pro#t='||token;
 footer:=E'\n\n—\n'||public.pro_mkt_business(p_owner)||E'\nRecibe este correo porque aceptó recibir información de este negocio. Para no recibir más correos: '||url||E'\nYou receive this email because you agreed to hear from this business. Unsubscribe: '||url;
 insert into public.pro_mkt_unsubscribe_tokens(token_hash,owner_id,contact_id) values(encode(sha256(convert_to(token,'UTF8')),'hex'),p_owner,p_contact);
 insert into public.pro_mkt_messages(owner_id,id,kind,campaign_id,draft_id,contact_id,to_email,subject,body,token_hash,mode,delivery)
 values(p_owner,mid,p_kind,p_campaign,p_draft,p_contact,coalesce(c.email,'unknown@invalid'),left(public.pro_mkt_render(p_owner,p_subject,c.name,p_link),200),left(public.pro_mkt_render(p_owner,p_body,c.name,p_link)||footer,12000),
  encode(sha256(convert_to(token,'UTF8')),'hex'),p_mode,case when p_mode='mock' then 'simulado' else 'queued' end);
 return mid;
end $$;
create or replace function public.pro_mkt_audience(p_owner uuid,p_segment text) returns setof public.pro_mkt_contacts
language sql stable security invoker set search_path=public,pg_temp as $$
 select c.* from public.pro_mkt_contacts c where c.owner_id=p_owner and c.consent='granted'
  and not exists(select 1 from public.pro_mkt_suppressions s where s.owner_id=c.owner_id and s.email_hash=c.email_hash)
  and (p_segment='all' or p_segment='clients' and c.client_id is not null or p_segment='leads' and c.lead_id is not null) order by c.created_at,c.id $$;
create or replace function public.pro_mkt_dispatch(p_owner uuid,p_campaign uuid,p_mode text,p_base text) returns integer
language plpgsql security invoker set search_path=public,pg_temp as $$
declare k public.pro_mkt_campaigns;c public.pro_mkt_contacts;n integer:=0;
begin
 select * into k from public.pro_mkt_campaigns where owner_id=p_owner and id=p_campaign for update;
 if not found then raise exception 'Campaign unavailable' using errcode='P0002';end if;
 if k.status not in('draft','scheduled') then raise exception 'Campaign already sent or cancelled' using errcode='40001';end if;
 for c in select * from public.pro_mkt_audience(p_owner,k.segment) limit 2000 loop
  perform public.pro_mkt_enqueue(p_owner,c.id,'campaign',k.id,null,k.subject,k.body,p_mode,p_base);n:=n+1;
 end loop;
 update public.pro_mkt_campaigns set status='sent',scheduled_at=null,sent_at=clock_timestamp(),recipients=n,mode=p_mode,revision=revision+1,updated_at=clock_timestamp() where owner_id=p_owner and id=p_campaign;
 return n;
end $$;
create or replace function public.pro_mkt_campaign_json(k public.pro_mkt_campaigns) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',k.id,'name',k.name,'subject',k.subject,'body',k.body,'segment',k.segment,'status',k.status,'scheduledAt',k.scheduled_at,'sentAt',k.sent_at,'recipients',k.recipients,'mode',k.mode,'revision',k.revision,'updatedAt',k.updated_at,
  'audience',(select count(*) from public.pro_mkt_audience(k.owner_id,k.segment))) $$;
create or replace function public.pro_mkt_default_automation(p_kind text) returns jsonb
language sql immutable security invoker set search_path=public,pg_temp as $$
 select case p_kind when 'quote_followup' then jsonb_build_object('subject','¿Pudo revisar la cotización?','body',E'Hola {{nombre}}:\n\nLe escribimos para saber si pudo revisar la cotización «{{enlace}}». Con gusto respondemos sus preguntas.\n\nSaludos,\n{{negocio}}','delayDays',3)
  else jsonb_build_object('subject','¿Cómo le fue con el trabajo?','body',E'Hola {{nombre}}:\n\nGracias por confiar en {{negocio}}. Si quedó satisfecho, nos ayudaría mucho una reseña en ContrataCR: {{enlace}}\n\nSaludos,\n{{negocio}}','delayDays',1) end $$;
create or replace function public.pro_mkt_automation_json(p_owner uuid,p_kind text) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select case when a.kind is null then jsonb_build_object('kind',p_kind,'enabled',false,'delayDays',(d->>'delayDays')::int,'subject',d->>'subject','body',d->>'body','revision',0)
  else jsonb_build_object('kind',a.kind,'enabled',a.enabled,'delayDays',a.delay_days,'subject',a.subject,'body',a.body,'revision',a.revision) end
 from (select public.pro_mkt_default_automation(p_kind) d) x left join public.pro_mkt_automations a on a.owner_id=p_owner and a.kind=p_kind $$;

-- ---------------------------------------------------------------- read
create or replace function public.pro_mkt_read(p_actor uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 perform public.pro_mkt_owner(p_actor);
 return jsonb_build_object(
  'ownerEmail',(select email from public.profiles where id=p_actor),'business',public.pro_mkt_business(p_actor),
  'contacts',coalesce((select jsonb_agg(public.pro_mkt_contact_json(c) order by c.created_at desc) from (select * from public.pro_mkt_contacts where owner_id=p_actor order by created_at desc limit 300) c),'[]'),
  'counts',jsonb_build_object('granted',(select count(*) from public.pro_mkt_audience(p_actor,'all')),'revoked',(select count(*) from public.pro_mkt_contacts where owner_id=p_actor and consent='revoked'),
   'suppressed',(select count(*) from public.pro_mkt_suppressions where owner_id=p_actor),
   'withoutConsent',(select count(*) from public.pro_clients k where k.user_id=p_actor and not k.archived and k.email~'@' and not exists(select 1 from public.pro_mkt_contacts c where c.owner_id=p_actor and c.email=lower(btrim(k.email)) and c.consent='granted'))),
  'candidates',coalesce((select jsonb_agg(jsonb_build_object('clientId',k.id,'name',k.name,'email',lower(btrim(k.email))) order by k.name) from (select * from public.pro_clients k where k.user_id=p_actor and not k.archived and k.email~'^[^@\s]+@[^@\s]+\.[^@\s]+$'
    and not exists(select 1 from public.pro_mkt_contacts c where c.owner_id=p_actor and c.email=lower(btrim(k.email))) order by k.name limit 100) k),'[]'),
  'templates',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'name',t.name,'subject',t.subject,'body',t.body,'archived',t.archived,'revision',t.revision) order by t.updated_at desc) from public.pro_mkt_templates t where t.owner_id=p_actor),'[]'),
  'campaigns',coalesce((select jsonb_agg(public.pro_mkt_campaign_json(k) order by k.updated_at desc) from public.pro_mkt_campaigns k where k.owner_id=p_actor),'[]'),
  'automations',jsonb_build_array(public.pro_mkt_automation_json(p_actor,'quote_followup'),public.pro_mkt_automation_json(p_actor,'review_request')),
  'drafts',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'kind',d.kind,'refKind',d.ref_kind,'refId',d.ref_id,'refLabel',d.ref_label,'contactId',d.contact_id,'to',c.email,'subject',d.subject,'body',d.body,'status',d.status,'createdAt',d.created_at,'decidedAt',d.decided_at) order by d.created_at desc)
   from (select * from public.pro_mkt_automation_drafts where owner_id=p_actor order by created_at desc limit 100) d join public.pro_mkt_contacts c on c.owner_id=d.owner_id and c.id=d.contact_id),'[]'),
  'outbox',coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'kind',m.kind,'campaignId',m.campaign_id,'draftId',m.draft_id,'to',m.to_email,'subject',m.subject,'body',m.body,'mode',m.mode,'delivery',m.delivery,'createdAt',m.created_at) order by m.created_at desc) from (select * from public.pro_mkt_messages where owner_id=p_actor order by created_at desc limit 60) m),'[]'));
end $$;

-- ---------------------------------------------------------------- mutate
create or replace function public.pro_mkt_mutate(p_actor uuid,p_input jsonb,p_mode text default 'mock',p_base text default null) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text:=p_input->>'action';aid uuid;receipt public.pro_mkt_actions;result jsonb;rid uuid;rev integer;c public.pro_mkt_contacts;k public.pro_mkt_campaigns;t public.pro_mkt_templates;d public.pro_mkt_automation_drafts;a public.pro_mkt_automations;
 n integer;mid uuid;owner_email text;at_value timestamptz;
begin
 perform public.pro_mkt_owner(p_actor);
 if jsonb_typeof(p_input)<>'object' or act not in('contact_consent','contact_revoke','template_save','template_archive','campaign_save','campaign_schedule','campaign_unschedule','campaign_cancel','campaign_send_now','test_send','automation_save','draft_decide') then
  raise exception 'Invalid marketing action' using errcode='22023';end if;
 if p_mode not in('mock','sandbox','production') then raise exception 'Invalid mode' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;exception when others then raise exception 'Invalid action id' using errcode='22023';end;
 if aid is null then raise exception 'Missing action id' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-mkt:'||p_actor::text,0));
 select * into receipt from public.pro_mkt_actions where owner_id=p_actor and action_id=aid;
 if found then if receipt.input is distinct from p_input then raise exception 'Action id reused' using errcode='22023';end if;return receipt.result;end if;
 rev:=case when jsonb_typeof(p_input->'revision')='number' then (p_input->>'revision')::integer else null end;
 if act='contact_consent' then
  if coalesce(length(p_input->>'consentText'),0) not between 20 and 1000 or p_input->>'evidence' not in('verbal','written','form','other') then raise exception 'Consent text and evidence are required' using errcode='22023';end if;
  if p_input->>'email' is null or lower(btrim(p_input->>'email'))!~'^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Invalid email' using errcode='22023';end if;
  if p_input->>'clientId' is not null and not exists(select 1 from public.pro_clients where user_id=p_actor and id=p_input->>'clientId') then raise exception 'Client unavailable' using errcode='P0002';end if;
  c:=public.pro_mkt_grant(p_actor,p_input->>'email',coalesce(nullif(btrim(p_input->>'name'),''),split_part(p_input->>'email','@',1)),'owner_recorded',p_input->>'consentText',jsonb_build_object('evidence',p_input->>'evidence','note',left(coalesce(p_input->>'note',''),300)),p_input->>'clientId',null);
  result:=jsonb_build_object('action',act,'contact',public.pro_mkt_contact_json(c));
 elsif act='contact_revoke' then
  rid:=(p_input->>'id')::uuid;select * into c from public.pro_mkt_contacts where owner_id=p_actor and id=rid;
  if not found then raise exception 'Contact unavailable' using errcode='P0002';end if;if c.revision<>rev then raise exception 'Contact changed' using errcode='40001';end if;
  perform public.pro_mkt_suppress(p_actor,rid,'owner','owner_revoked');select * into c from public.pro_mkt_contacts where owner_id=p_actor and id=rid;
  result:=jsonb_build_object('action',act,'contact',public.pro_mkt_contact_json(c));
 elsif act in('template_save','template_archive') then
  rid:=(p_input->>'id')::uuid;select * into t from public.pro_mkt_templates where owner_id=p_actor and id=rid for update;
  if coalesce(t.revision,0)<>rev then raise exception 'Template changed' using errcode='40001';end if;
  if act='template_archive' then if not found then raise exception 'Template unavailable' using errcode='P0002';end if;
   update public.pro_mkt_templates set archived=not archived,revision=revision+1,updated_at=clock_timestamp() where owner_id=p_actor and id=rid returning * into t;
  elsif not found then insert into public.pro_mkt_templates(owner_id,id,name,subject,body) values(p_actor,rid,btrim(p_input->>'name'),btrim(p_input->>'subject'),p_input->>'body') returning * into t;
  else update public.pro_mkt_templates set name=btrim(p_input->>'name'),subject=btrim(p_input->>'subject'),body=p_input->>'body',revision=revision+1,updated_at=clock_timestamp() where owner_id=p_actor and id=rid returning * into t;end if;
  result:=jsonb_build_object('action',act,'template',jsonb_build_object('id',t.id,'name',t.name,'subject',t.subject,'body',t.body,'archived',t.archived,'revision',t.revision));
 elsif act like 'campaign_%' or act='test_send' then
  rid:=(p_input->>'id')::uuid;select * into k from public.pro_mkt_campaigns where owner_id=p_actor and id=rid for update;
  if act='campaign_save' then
   if coalesce(k.revision,0)<>rev then raise exception 'Campaign changed' using errcode='40001';end if;
   if found and k.status not in('draft','scheduled') then raise exception 'Only drafts can be edited' using errcode='40001';end if;
   if not found then insert into public.pro_mkt_campaigns(owner_id,id,name,subject,body,segment) values(p_actor,rid,btrim(p_input->>'name'),btrim(p_input->>'subject'),p_input->>'body',coalesce(p_input->>'segment','all')) returning * into k;
   else update public.pro_mkt_campaigns set name=btrim(p_input->>'name'),subject=btrim(p_input->>'subject'),body=p_input->>'body',segment=coalesce(p_input->>'segment','all'),revision=revision+1,updated_at=clock_timestamp() where owner_id=p_actor and id=rid returning * into k;end if;
  else
   if not found then raise exception 'Campaign unavailable' using errcode='P0002';end if;
   if act<>'test_send' and k.revision<>rev then raise exception 'Campaign changed' using errcode='40001';end if;
   if act='test_send' then
    select email into owner_email from public.profiles where id=p_actor;
    mid:=gen_random_uuid();
    insert into public.pro_mkt_messages(owner_id,id,kind,to_email,subject,body,mode,delivery) values(p_actor,mid,'test',owner_email,left('[Prueba] '||public.pro_mkt_render(p_actor,k.subject,'Cliente de prueba',null),200),
     left(public.pro_mkt_render(p_actor,k.body,'Cliente de prueba',null)||E'\n\n— Envío de prueba: solo a su propio correo. / Test send: only to your own email.',12000),p_mode,case when p_mode='mock' then 'simulado' else 'queued' end);
   elsif act='campaign_schedule' then
    begin at_value:=(p_input->>'scheduledAt')::timestamptz;exception when others then raise exception 'Invalid date' using errcode='22023';end;
    if at_value is null or at_value<=now() then raise exception 'Schedule a future time' using errcode='22023';end if;
    if k.status<>'draft' then raise exception 'Only drafts can be scheduled' using errcode='40001';end if;
    update public.pro_mkt_campaigns set status='scheduled',scheduled_at=at_value,revision=revision+1,updated_at=clock_timestamp() where owner_id=p_actor and id=rid returning * into k;
   elsif act='campaign_unschedule' then
    if k.status<>'scheduled' then raise exception 'Not scheduled' using errcode='40001';end if;
    update public.pro_mkt_campaigns set status='draft',scheduled_at=null,revision=revision+1,updated_at=clock_timestamp() where owner_id=p_actor and id=rid returning * into k;
   elsif act='campaign_cancel' then
    if k.status not in('draft','scheduled') then raise exception 'Already sent or cancelled' using errcode='40001';end if;
    update public.pro_mkt_campaigns set status='cancelled',scheduled_at=null,revision=revision+1,updated_at=clock_timestamp() where owner_id=p_actor and id=rid returning * into k;
   else n:=public.pro_mkt_dispatch(p_actor,rid,p_mode,p_base);select * into k from public.pro_mkt_campaigns where owner_id=p_actor and id=rid;
   end if;
  end if;
  result:=jsonb_build_object('action',act,'campaign',public.pro_mkt_campaign_json(k),'messageId',mid);
 elsif act='automation_save' then
  if p_input->>'kind' not in('quote_followup','review_request') then raise exception 'Invalid automation' using errcode='22023';end if;
  select * into a from public.pro_mkt_automations where owner_id=p_actor and kind=p_input->>'kind' for update;
  if coalesce(a.revision,0)<>rev then raise exception 'Automation changed' using errcode='40001';end if;
  insert into public.pro_mkt_automations(owner_id,kind,enabled,delay_days,subject,body) values(p_actor,p_input->>'kind',(p_input->>'enabled')::boolean,(p_input->>'delayDays')::integer,btrim(p_input->>'subject'),p_input->>'body')
  on conflict(owner_id,kind) do update set enabled=excluded.enabled,delay_days=excluded.delay_days,subject=excluded.subject,body=excluded.body,revision=pro_mkt_automations.revision+1,updated_at=clock_timestamp();
  result:=jsonb_build_object('action',act,'automation',public.pro_mkt_automation_json(p_actor,p_input->>'kind'));
 else -- draft_decide
  rid:=(p_input->>'id')::uuid;select * into d from public.pro_mkt_automation_drafts where owner_id=p_actor and id=rid for update;
  if not found then raise exception 'Draft unavailable' using errcode='P0002';end if;
  if d.status<>'pending_approval' then raise exception 'Already decided' using errcode='40001';end if;
  if p_input->>'decision'='approve' then
   mid:=public.pro_mkt_enqueue(p_actor,d.contact_id,'automation',null,d.id,d.subject,d.body,p_mode,p_base);
   update public.pro_mkt_automation_drafts set status='approved',decided_at=clock_timestamp(),message_id=mid where owner_id=p_actor and id=rid;
  elsif p_input->>'decision'='reject' then update public.pro_mkt_automation_drafts set status='rejected',decided_at=clock_timestamp() where owner_id=p_actor and id=rid;
  else raise exception 'Invalid decision' using errcode='22023';end if;
  result:=jsonb_build_object('action',act,'draftId',rid,'status',(select status from public.pro_mkt_automation_drafts where owner_id=p_actor and id=rid),'messageId',mid);
 end if;
 insert into public.pro_mkt_history(owner_id,action_id,action,entity,entity_id,snapshot) values(p_actor,aid,act,split_part(act,'_',1),coalesce(rid::text,c.id::text,p_input->>'kind',''),result);
 insert into public.pro_mkt_actions(owner_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

-- Scheduled campaigns that are due: claimed atomically (two tabs never send twice).
create or replace function public.pro_mkt_run_due(p_actor uuid,p_mode text,p_base text) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare k record;sent jsonb:='[]';
begin
 perform public.pro_mkt_owner(p_actor);
 for k in select id from public.pro_mkt_campaigns where owner_id=p_actor and status='scheduled' and scheduled_at<=now() order by scheduled_at for update skip locked loop
  sent:=sent||jsonb_build_array(jsonb_build_object('id',k.id,'recipients',public.pro_mkt_dispatch(p_actor,k.id,p_mode,p_base)));
 end loop;
 return jsonb_build_object('sent',sent);
end $$;

-- Automations: find what happened (quote shared / job completed) and create DRAFTS that wait for approval.
create or replace function public.pro_mkt_automation_scan(p_actor uuid,p_base text) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare a public.pro_mkt_automations;r record;n integer:=0;slug text;review_link text;
begin
 perform public.pro_mkt_owner(p_actor);perform public.pro_mkt_base_ok(p_base);
 perform pg_advisory_xact_lock(hashtextextended('pro-mkt:'||p_actor::text,0));
 select p.slug into slug from public.professionals p where p.profile_id=p_actor;
 review_link:=p_base||'/profesionales/'||coalesce(slug,'');
 select * into a from public.pro_mkt_automations where owner_id=p_actor and kind='quote_followup' and enabled;
 if found then
  for r in select v.id,e.title,c.id contact_id from public.pro_private_estimate_publications v
    join public.pro_private_estimate_publication_states s on s.publication_id=v.id and s.status in('awaiting_claim','shared')
    join public.pro_private_estimates e on e.owner_id=v.owner_id and e.id=v.estimate_id and not e.archived
    join public.pro_clients k on k.user_id=v.owner_id and k.id=v.client_id
    join public.pro_mkt_contacts c on c.owner_id=v.owner_id and c.email=lower(btrim(k.email))
   where v.owner_id=p_actor and v.created_at<=now()-make_interval(days=>a.delay_days) and c.consent='granted'
    and not exists(select 1 from public.pro_mkt_suppressions x where x.owner_id=c.owner_id and x.email_hash=c.email_hash)
    and not exists(select 1 from public.pro_mkt_automation_drafts d where d.owner_id=p_actor and d.kind='quote_followup' and d.ref_id=v.id::text) limit 100 loop
   insert into public.pro_mkt_automation_drafts(owner_id,id,kind,ref_kind,ref_id,ref_label,contact_id,subject,body)
   values(p_actor,gen_random_uuid(),'quote_followup','estimate_publication',r.id::text,left(r.title,200),r.contact_id,a.subject,replace(a.body,'{{enlace}}',r.title));n:=n+1;
  end loop;
 end if;
 select * into a from public.pro_mkt_automations where owner_id=p_actor and kind='review_request' and enabled;
 if found then
  for r in select w.id,w.service,c.id contact_id from public.pro_work w
    join public.pro_clients k on k.user_id=w.user_id and k.id=w."clientId"
    join public.pro_mkt_contacts c on c.owner_id=w.user_id and c.email=lower(btrim(k.email))
   where w.user_id=p_actor and w.stage='completed' and not w.cancelled and c.consent='granted'
    and not exists(select 1 from public.pro_mkt_suppressions x where x.owner_id=c.owner_id and x.email_hash=c.email_hash)
    and not exists(select 1 from public.pro_mkt_automation_drafts d where d.owner_id=p_actor and d.kind='review_request' and d.ref_id=w.id) limit 100 loop
   insert into public.pro_mkt_automation_drafts(owner_id,id,kind,ref_kind,ref_id,ref_label,contact_id,subject,body)
   values(p_actor,gen_random_uuid(),'review_request','work',r.id,left(r.service,200),r.contact_id,a.subject,replace(a.body,'{{enlace}}',review_link));n:=n+1;
  end loop;
 end if;
 return jsonb_build_object('created',n);
end $$;

-- ---------------------------------------------------------------- public unsubscribe (token only)
create or replace function public.pro_mkt_unsubscribe(p_token text,p_confirm boolean) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare tk public.pro_mkt_unsubscribe_tokens;c public.pro_mkt_contacts;already boolean;
begin
 if p_token is null or p_token!~'^[a-f0-9]{64}$' then raise exception 'Invalid link' using errcode='22023';end if;
 select * into tk from public.pro_mkt_unsubscribe_tokens where token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex') for update;
 if not found then raise exception 'Link unavailable' using errcode='P0002';end if;
 select * into c from public.pro_mkt_contacts where owner_id=tk.owner_id and id=tk.contact_id;
 already:=exists(select 1 from public.pro_mkt_suppressions where owner_id=tk.owner_id and email_hash=c.email_hash);
 if p_confirm and not already then
  perform public.pro_mkt_suppress(tk.owner_id,tk.contact_id,'unsubscribed','unsubscribe_link');
  update public.pro_mkt_unsubscribe_tokens set used_at=clock_timestamp() where token_hash=tk.token_hash;
 end if;
 return jsonb_build_object('business',public.pro_mkt_business(tk.owner_id),'unsubscribed',already or p_confirm,'already',already);
end $$;

-- ---------------------------------------------------------------- double opt-in (post-security fixes, Ley 8968)
/** Site-form tick → «pending» contact + one confirmation email (mock: stored «simulado», never sent). Silent for an
 *  address that unsubscribed or already consented, and at most one new email per address per 24 h (no flooding). */
create or replace function public.pro_mkt_request_confirmation(p_owner uuid,p_email text,p_name text,p_text text,p_evidence jsonb,p_client text,p_lead uuid,p_base text,p_language text default 'es') returns void
language plpgsql security invoker set search_path=public,pg_temp as $$
declare c public.pro_mkt_contacts;e text:=lower(btrim(p_email));token text:=replace(gen_random_uuid()::text||gen_random_uuid()::text,'-','');url text;en boolean:=p_language='en';biz text;
begin
 if coalesce(length(p_text),0) not between 20 and 1000 then raise exception 'Consent text is required' using errcode='22023';end if;
 url:=public.pro_mkt_base_ok(p_base)||case when en then '/en' else '' end||'/confirmar-pro#t='||token;
 if exists(select 1 from public.pro_mkt_suppressions where owner_id=p_owner and email_hash=public.pro_mkt_email_hash(e)) then return;end if;
 select * into c from public.pro_mkt_contacts where owner_id=p_owner and email=e for update;
 if found and c.consent='granted' then return;end if;
 if found and c.consent='pending' and exists(select 1 from public.pro_mkt_confirmations k where k.owner_id=p_owner and k.contact_id=c.id and k.used_at is null and k.created_at>clock_timestamp()-interval '24 hours') then return;end if;
 if found then
  update public.pro_mkt_contacts set consent='pending',consent_source='site_form',consent_text=p_text,consent_at=null,revoked_at=null,confirmation_requested_at=clock_timestamp(),confirmed_at=null,
   client_id=coalesce(client_id,p_client),lead_id=coalesce(lead_id,p_lead),revision=revision+1,updated_at=clock_timestamp() where owner_id=p_owner and id=c.id returning * into c;
 else
  insert into public.pro_mkt_contacts(owner_id,id,email,name,client_id,lead_id,consent,consent_source,consent_text,confirmation_requested_at)
  values(p_owner,gen_random_uuid(),e,btrim(p_name),p_client,p_lead,'pending','site_form',p_text,clock_timestamp()) returning * into c;
 end if;
 insert into public.pro_mkt_consent_events(owner_id,id,contact_id,event,source,consent_text,evidence) values(p_owner,gen_random_uuid(),c.id,'requested','site_form',p_text,coalesce(p_evidence,'{}'));
 biz:=public.pro_mkt_business(p_owner);
 insert into public.pro_mkt_confirmations(token_hash,owner_id,contact_id,to_email,subject,body,expires_at)
 values(encode(sha256(convert_to(token,'UTF8')),'hex'),p_owner,c.id,c.email,left(case when en then 'Confirm that you want to receive emails from '||biz else 'Confirme que desea recibir correos de '||biz end,200),
  left(case when en then 'Hello '||split_part(c.name,' ',1)||E':\n\nYou asked '||biz||' to send you news and offers by email. To confirm, open this link (valid for 7 days):\n'||url||E'\n\nIf it was not you, ignore this email: you will receive nothing.'
   else 'Hola '||split_part(c.name,' ',1)||E':\n\nUsted pidió a '||biz||' recibir novedades y promociones por correo. Para confirmarlo, abra este enlace (válido 7 días):\n'||url||E'\n\nSi no fue usted, ignore este correo: no recibirá nada.' end,4000),
  clock_timestamp()+interval '7 days');
end $$;
/** Public confirmation (token only). «peek» shows the business; «confirm» grants consent once (idempotent). */
create or replace function public.pro_mkt_confirm(p_token text,p_confirm boolean) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare k public.pro_mkt_confirmations;c public.pro_mkt_contacts;suppressed boolean;
begin
 if p_token is null or p_token!~'^[a-f0-9]{64}$' then raise exception 'Invalid link' using errcode='22023';end if;
 select * into k from public.pro_mkt_confirmations where token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex') for update;
 if not found then raise exception 'Link unavailable' using errcode='P0002';end if;
 select * into c from public.pro_mkt_contacts where owner_id=k.owner_id and id=k.contact_id for update;
 suppressed:=exists(select 1 from public.pro_mkt_suppressions where owner_id=k.owner_id and email_hash=c.email_hash);
 if k.used_at is not null then return jsonb_build_object('business',public.pro_mkt_business(k.owner_id),'confirmed',c.consent='granted' and not suppressed,'already',true,'expired',false);end if;
 if k.expires_at<=clock_timestamp() or suppressed or c.consent not in('pending','granted') then
  return jsonb_build_object('business',public.pro_mkt_business(k.owner_id),'confirmed',false,'already',false,'expired',true);end if;
 if p_confirm then
  if c.consent='pending' then
   update public.pro_mkt_contacts set consent='granted',consent_at=clock_timestamp(),confirmed_at=clock_timestamp(),revision=revision+1,updated_at=clock_timestamp() where owner_id=c.owner_id and id=c.id;
   insert into public.pro_mkt_consent_events(owner_id,id,contact_id,event,source,consent_text,evidence)
   values(c.owner_id,gen_random_uuid(),c.id,'confirmed','confirmation_link',c.consent_text,jsonb_build_object('requestedAt',c.confirmation_requested_at,'emailSentAt',k.created_at));
  end if;
  update public.pro_mkt_confirmations set used_at=clock_timestamp() where token_hash=k.token_hash;
 end if;
 return jsonb_build_object('business',public.pro_mkt_business(k.owner_id),'confirmed',p_confirm,'already',false,'expired',false);
end $$;

-- ---------------------------------------------------------------- posture
do $$declare n text;begin foreach n in array array['pro_mkt_contacts','pro_mkt_consent_events','pro_mkt_suppressions','pro_mkt_unsubscribe_tokens','pro_mkt_confirmations','pro_mkt_templates','pro_mkt_campaigns','pro_mkt_automations','pro_mkt_automation_drafts','pro_mkt_messages','pro_mkt_actions','pro_mkt_history'] loop
 execute format('alter table public.%I enable row level security',n);execute format('revoke all on public.%I from public,anon,authenticated,service_role',n);execute format('grant select,insert,update on public.%I to service_role',n);
end loop;end $$;
do $$declare f regprocedure;begin
 for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'pro\_mkt\_%' loop
  execute format('revoke all on function %s from public,anon,authenticated',f);
  if f::text not like 'pro_mkt_immutable(%' and f::text not like 'pro_mkt_message_guard(%' and f::text not like 'pro_mkt_draft_guard(%' and f::text not like 'pro_mkt_confirmation_guard(%' then execute format('grant execute on function %s to service_role',f);end if;
 end loop;end $$;
notify pgrst,'reload schema';
commit;

-- ===== ads-tracking-local.sql =====
-- LOCAL PRO ONLY. Round 6D (2026-11-13): ad / lead-capture tracking for professionals (row 70).
-- * Tracking campaigns with UTM parameters and a short code; the link points to the professional's website
--   (/sitio/<slug>?utm_…&cc=<code>) or public profile. Visits are counted per day (no personal data).
-- * Lead-source attribution: a website request with a campaign code is attributed to it (first touch, immutable)
--   and its lead in the existing lead center gets the matching origin channel (advertising / social / website).
--   The owner may attribute a manual lead to a campaign once.
-- * Cost entries per campaign are append-only; a mistake is corrected with a void entry (once per cost).
-- * The report uses ONLY real data of the account: leads (pro_lead_center_records), conversions
--   (pro_manual_lead_works with a live job) and the agreed/paid amounts of those jobs (pro_work_account), against
--   the costs the owner entered. No ad platform is called (Meta/Google adapters are documented stubs, inactive).
-- Tables: RLS on, service_role only; costs/attributions/history immutable; functions security invoker.
begin;
create table if not exists public.pro_ad_campaigns(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,
 name text not null check(length(btrim(name)) between 1 and 120),
 channel text not null check(channel in('meta','google','instagram','tiktok','whatsapp','email','print','radio','other')),
 landing text not null default 'site' check(landing in('site','profile')),
 code text not null check(code~'^[a-z0-9]{6,16}$'),
 utm_source text not null check(utm_source~'^[a-z0-9._-]{1,60}$'),utm_medium text not null check(utm_medium~'^[a-z0-9._-]{1,60}$'),
 utm_campaign text not null check(utm_campaign~'^[a-z0-9._-]{1,80}$'),utm_content text check(utm_content is null or utm_content~'^[a-z0-9._-]{1,80}$'),
 archived boolean not null default false,revision integer not null default 1 check(revision>0),
 created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,id),unique(owner_id,code)
);
create table if not exists public.pro_ad_costs(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,campaign_id uuid not null,
 kind text not null check(kind in('cost','void')),void_of uuid,
 spent_on date not null check(spent_on between date'2000-01-01' and date'2100-12-31'),
 amount_cents bigint not null check(amount_cents between 1 and 100000000000),currency text not null default 'CRC' check(currency='CRC'),
 note text not null default '' check(length(note)<=300),created_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,id),unique(owner_id,void_of),check((kind='void')=(void_of is not null)),
 foreign key(owner_id,campaign_id) references public.pro_ad_campaigns(owner_id,id) on delete cascade
);
create table if not exists public.pro_ad_visits(
 owner_id uuid not null references public.profiles(id) on delete cascade,campaign_id uuid not null,day date not null,
 visits integer not null default 0 check(visits>=0),primary key(owner_id,campaign_id,day),
 foreign key(owner_id,campaign_id) references public.pro_ad_campaigns(owner_id,id) on delete cascade
);
create table if not exists public.pro_lead_attributions(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 lead_kind text not null default 'manual' check(lead_kind='manual'),lead_id uuid not null,campaign_id uuid,
 source text not null check(source in('site_form','owner')),
 utm jsonb not null default '{}' check(jsonb_typeof(utm)='object' and octet_length(utm::text)<=1024),
 at timestamptz not null default clock_timestamp(),primary key(owner_id,lead_id),
 foreign key(owner_id,lead_kind,lead_id) references public.pro_lead_center_records(owner_id,kind,id) on delete cascade,
 foreign key(owner_id,campaign_id) references public.pro_ad_campaigns(owner_id,id) on delete cascade
);
create table if not exists public.pro_ad_actions(
 owner_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 input jsonb not null,result jsonb not null,created_at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id)
);
create or replace function public.pro_ad_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Costs, attributions and receipts are immutable (void a cost instead)' using errcode='23514';end $$;
do $$declare t text;begin foreach t in array array['pro_ad_costs','pro_lead_attributions','pro_ad_actions'] loop
 execute format('drop trigger if exists %I on public.%I',t||'_immutable',t);
 execute format('create trigger %I before update on public.%I for each row execute function public.pro_ad_immutable()',t||'_immutable',t);
end loop;end $$;

create or replace function public.pro_ad_channel_origin(p_channel text) returns text
language sql immutable security invoker set search_path=public,pg_temp as $$
 select case when p_channel is null then 'website' when p_channel in('meta','google','print','radio') then 'advertising' when p_channel in('instagram','tiktok','whatsapp') then 'social' else 'other' end $$;
create or replace function public.pro_ad_campaign_json(k public.pro_ad_campaigns) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',k.id,'name',k.name,'channel',k.channel,'landing',k.landing,'code',k.code,'utm',jsonb_strip_nulls(jsonb_build_object('source',k.utm_source,'medium',k.utm_medium,'campaign',k.utm_campaign,'content',k.utm_content)),'archived',k.archived,'revision',k.revision,'createdAt',k.created_at) $$;
create or replace function public.pro_ad_cr_day(p_at timestamptz) returns date
language sql stable security invoker set search_path=public,pg_temp as $$ select (p_at at time zone 'America/Costa_Rica')::date $$;

-- Report from real data only. Conversion = an explicit, still valid lead→job link (same rule as the lead funnel).
create or replace function public.pro_ad_report(p_actor uuid,p_from date,p_to date) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare rows jsonb;totals jsonb;
begin
 perform public.pro_mkt_owner(p_actor);
 if p_from is null or p_to is null or p_from>p_to or p_to-p_from>3660 then raise exception 'Invalid period' using errcode='22023';end if;
 with leads as materialized(
  select a.campaign_id,r.id lead_id,m.work_id_text work_id
  from public.pro_lead_attributions a join public.pro_lead_center_records r on r.owner_id=a.owner_id and r.kind='manual' and r.id=a.lead_id
  left join public.pro_manual_lead_works m on m.owner_id=a.owner_id and m.lead_id=a.lead_id
   and exists(select 1 from public.pro_work w where w.user_id=m.owner_id and w.id=m.work_id_text and w."clientId"=m.source_client_id and not w.cancelled)
  where a.owner_id=p_actor and public.pro_ad_cr_day(r.created_at) between p_from and p_to),
 money as(select l.*,(public.pro_work_account(p_actor,l.work_id)->>'agreedCents')::bigint agreed,(public.pro_work_account(p_actor,l.work_id)->>'paidCents')::bigint paid from leads l),
 keys as(select id campaign_id from public.pro_ad_campaigns where owner_id=p_actor union select null::uuid),
 per as(select k.campaign_id,
  coalesce((select sum(visits) from public.pro_ad_visits v where v.owner_id=p_actor and v.campaign_id=k.campaign_id and v.day between p_from and p_to),0)::bigint visits,
  (select count(*) from money m where m.campaign_id is not distinct from k.campaign_id)::bigint leads,
  (select count(*) from money m where m.campaign_id is not distinct from k.campaign_id and m.work_id is not null)::bigint converted,
  coalesce((select sum(agreed) from money m where m.campaign_id is not distinct from k.campaign_id and m.work_id is not null),0)::bigint agreed,
  coalesce((select sum(paid) from money m where m.campaign_id is not distinct from k.campaign_id and m.work_id is not null),0)::bigint paid,
  coalesce((select sum(case when c.kind='cost' then c.amount_cents else -c.amount_cents end) from public.pro_ad_costs c where c.owner_id=p_actor and c.campaign_id=k.campaign_id
    and (case when c.kind='cost' then c.spent_on else (select o.spent_on from public.pro_ad_costs o where o.owner_id=c.owner_id and o.id=c.void_of) end) between p_from and p_to),0)::bigint cost
  from keys k)
 select coalesce(jsonb_agg(jsonb_build_object('campaignId',p.campaign_id,'name',k.name,'channel',k.channel,'archived',coalesce(k.archived,false),'visits',p.visits,'leads',p.leads,'converted',p.converted,'agreedCents',p.agreed,'paidCents',p.paid,'costCents',p.cost,
   'costPerLeadCents',case when p.leads>0 and p.cost>0 then round(p.cost::numeric/p.leads)::bigint end,
   'roiBps',case when p.cost>0 then round((p.agreed-p.cost)::numeric*10000/p.cost)::bigint end) order by k.created_at nulls last),'[]'),
  jsonb_build_object('visits',sum(p.visits),'leads',sum(p.leads),'converted',sum(p.converted),'agreedCents',sum(p.agreed),'paidCents',sum(p.paid),'costCents',sum(p.cost),
   'costPerLeadCents',case when sum(p.leads)>0 and sum(p.cost)>0 then round(sum(p.cost)/sum(p.leads))::bigint end,'roiBps',case when sum(p.cost)>0 then round((sum(p.agreed)-sum(p.cost))*10000/sum(p.cost))::bigint end)
 into rows,totals from per p left join public.pro_ad_campaigns k on k.owner_id=p_actor and k.id=p.campaign_id
 where p.campaign_id is not null or p.leads>0;
 return jsonb_build_object('from',to_char(p_from,'YYYY-MM-DD'),'to',to_char(p_to,'YYYY-MM-DD'),'rows',rows,'totals',totals);
end $$;
create or replace function public.pro_ad_read(p_actor uuid,p_from date,p_to date) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 perform public.pro_mkt_owner(p_actor);
 return jsonb_build_object(
  'campaigns',coalesce((select jsonb_agg(public.pro_ad_campaign_json(k) order by k.created_at) from public.pro_ad_campaigns k where k.owner_id=p_actor),'[]'),
  'costs',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'campaignId',c.campaign_id,'kind',c.kind,'voidOf',c.void_of,'spentOn',to_char(c.spent_on,'YYYY-MM-DD'),'amountCents',c.amount_cents,'note',c.note,'createdAt',c.created_at,
    'voided',exists(select 1 from public.pro_ad_costs v where v.owner_id=c.owner_id and v.void_of=c.id)) order by c.created_at desc) from (select * from public.pro_ad_costs where owner_id=p_actor order by created_at desc limit 200) c),'[]'),
  'unattributed',coalesce((select jsonb_agg(jsonb_build_object('leadId',r.id,'title',r.title,'createdAt',r.created_at) order by r.created_at desc) from (select * from public.pro_lead_center_records r where r.owner_id=p_actor and r.kind='manual' and not r.archived
    and not exists(select 1 from public.pro_lead_attributions a where a.owner_id=r.owner_id and a.lead_id=r.id) order by r.created_at desc limit 50) r),'[]'),
  'site',(select jsonb_build_object('slug',s.slug,'published',s.published_version is not null) from public.pro_sites s where s.owner_id=p_actor),
  'profileSlug',(select slug from public.professionals where profile_id=p_actor),
  'report',public.pro_ad_report(p_actor,p_from,p_to));
end $$;
create or replace function public.pro_ad_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text:=p_input->>'action';aid uuid;receipt public.pro_ad_actions;result jsonb;rid uuid;rev integer;k public.pro_ad_campaigns;cost public.pro_ad_costs;slugged text;src text;med text;
begin
 perform public.pro_mkt_owner(p_actor);
 if jsonb_typeof(p_input)<>'object' or act not in('campaign_save','campaign_archive','cost_add','cost_void','attribute') then raise exception 'Invalid tracking action' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;rid:=(p_input->>'id')::uuid;exception when others then raise exception 'Invalid ids' using errcode='22023';end;
 if aid is null then raise exception 'Missing action id' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-ads:'||p_actor::text,0));
 select * into receipt from public.pro_ad_actions where owner_id=p_actor and action_id=aid;
 if found then if receipt.input is distinct from p_input then raise exception 'Action id reused' using errcode='22023';end if;return receipt.result;end if;
 rev:=case when jsonb_typeof(p_input->'revision')='number' then (p_input->>'revision')::integer else null end;
 if act in('campaign_save','campaign_archive') then
  select * into k from public.pro_ad_campaigns where owner_id=p_actor and id=rid for update;
  if coalesce(k.revision,0)<>rev then raise exception 'Campaign changed' using errcode='40001';end if;
  if act='campaign_archive' then
   if not found then raise exception 'Campaign unavailable' using errcode='P0002';end if;
   update public.pro_ad_campaigns set archived=not archived,revision=revision+1,updated_at=clock_timestamp() where owner_id=p_actor and id=rid returning * into k;
  else
   slugged:=left(trim(both '-' from regexp_replace(lower(translate(btrim(p_input->>'name'),'áéíóúüñÁÉÍÓÚÜÑ','aeiouunAEIOUUN')),'[^a-z0-9]+','-','g')),80);
   src:=coalesce(nullif(lower(btrim(p_input->>'utmSource')),''),case p_input->>'channel' when 'meta' then 'facebook' when 'google' then 'google' when 'instagram' then 'instagram' when 'tiktok' then 'tiktok' when 'whatsapp' then 'whatsapp' when 'email' then 'email' when 'print' then 'impreso' when 'radio' then 'radio' else 'otro' end);
   med:=coalesce(nullif(lower(btrim(p_input->>'utmMedium')),''),case p_input->>'channel' when 'meta' then 'cpc' when 'google' then 'cpc' when 'email' then 'email' when 'print' then 'offline' when 'radio' then 'offline' else 'social' end);
   if not found then
    insert into public.pro_ad_campaigns(owner_id,id,name,channel,landing,code,utm_source,utm_medium,utm_campaign,utm_content)
    values(p_actor,rid,btrim(p_input->>'name'),p_input->>'channel',coalesce(p_input->>'landing','site'),substr(md5(p_actor::text||rid::text),1,8),src,med,coalesce(nullif(lower(btrim(p_input->>'utmCampaign')),''),nullif(slugged,''),'campana'),nullif(lower(btrim(coalesce(p_input->>'utmContent',''))),''))
    returning * into k;
   else
    update public.pro_ad_campaigns set name=btrim(p_input->>'name'),channel=p_input->>'channel',landing=coalesce(p_input->>'landing','site'),utm_source=src,utm_medium=med,
     utm_campaign=coalesce(nullif(lower(btrim(p_input->>'utmCampaign')),''),nullif(slugged,''),'campana'),utm_content=nullif(lower(btrim(coalesce(p_input->>'utmContent',''))),''),revision=revision+1,updated_at=clock_timestamp()
    where owner_id=p_actor and id=rid returning * into k;
   end if;
  end if;
  result:=jsonb_build_object('action',act,'campaign',public.pro_ad_campaign_json(k));
 elsif act='cost_add' then
  if not exists(select 1 from public.pro_ad_campaigns where owner_id=p_actor and id=(p_input->>'campaignId')::uuid) then raise exception 'Campaign unavailable' using errcode='P0002';end if;
  insert into public.pro_ad_costs(owner_id,id,campaign_id,kind,spent_on,amount_cents,note) values(p_actor,rid,(p_input->>'campaignId')::uuid,'cost',(p_input->>'spentOn')::date,(p_input->>'amountCents')::bigint,left(coalesce(p_input->>'note',''),300)) returning * into cost;
  result:=jsonb_build_object('action',act,'costId',cost.id);
 elsif act='cost_void' then
  select * into cost from public.pro_ad_costs where owner_id=p_actor and id=(p_input->>'costId')::uuid and kind='cost';
  if not found then raise exception 'Cost unavailable' using errcode='P0002';end if;
  if exists(select 1 from public.pro_ad_costs where owner_id=p_actor and void_of=cost.id) then raise exception 'Already voided' using errcode='40001';end if;
  insert into public.pro_ad_costs(owner_id,id,campaign_id,kind,void_of,spent_on,amount_cents,note) values(p_actor,rid,cost.campaign_id,'void',cost.id,current_date,cost.amount_cents,left(coalesce(p_input->>'note',''),300));
  result:=jsonb_build_object('action',act,'costId',rid);
 else
  if not exists(select 1 from public.pro_lead_center_records where owner_id=p_actor and kind='manual' and id=(p_input->>'leadId')::uuid) then raise exception 'Lead unavailable' using errcode='P0002';end if;
  if not exists(select 1 from public.pro_ad_campaigns where owner_id=p_actor and id=(p_input->>'campaignId')::uuid) then raise exception 'Campaign unavailable' using errcode='P0002';end if;
  if exists(select 1 from public.pro_lead_attributions where owner_id=p_actor and lead_id=(p_input->>'leadId')::uuid) then raise exception 'Lead already attributed' using errcode='40001';end if;
  insert into public.pro_lead_attributions(owner_id,lead_id,campaign_id,source) values(p_actor,(p_input->>'leadId')::uuid,(p_input->>'campaignId')::uuid,'owner');
  result:=jsonb_build_object('action',act,'leadId',p_input->>'leadId','campaignId',p_input->>'campaignId');
 end if;
 insert into public.pro_ad_actions(owner_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

do $$declare n text;begin foreach n in array array['pro_ad_campaigns','pro_ad_costs','pro_ad_visits','pro_lead_attributions','pro_ad_actions'] loop
 execute format('alter table public.%I enable row level security',n);execute format('revoke all on public.%I from public,anon,authenticated,service_role',n);execute format('grant select,insert,update on public.%I to service_role',n);
end loop;end $$;
do $$declare f regprocedure;begin
 for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'pro\_ad\_%' loop
  execute format('revoke all on function %s from public,anon,authenticated',f);
  if f::text not like 'pro_ad_immutable(%' then execute format('grant execute on function %s to service_role',f);end if;
 end loop;end $$;
notify pgrst,'reload schema';
commit;

-- ===== pro-sites-local.sql =====
-- LOCAL PRO ONLY. Round 6D (2026-11-13): website builder for professionals (row 69).
-- * One site per owner: slug (served locally at /sitio/<slug>), theme preset, DRAFT content (sections: hero,
--   services, portfolio, reviews, service area, contact form) with CAS revision and idempotent actionId.
-- * Publish freezes the draft into an immutable numbered VERSION (no UPDATE; no DELETE grant). The public reader
--   only ever returns the latest published version: draft edits are invisible until the next publish; an
--   unpublished site returns nothing. Portfolio photos must come from the owner's own ContrataCR profile.
-- * Reviews shown are the professional's PUBLISHED ContrataCR reviews (moderation_status='published'), read live,
--   reviewer reduced to first name + initial. No owner id, email or internal ids are exposed.
-- * The contact/project request form creates a customer + a lead in the existing lead center (through
--   pro_lead_origin_create, origin channel website/advertising/social), attributes it to the tracking campaign
--   (ads-tracking-local.sql) and records marketing consent ONLY when the visitor ticked it (email-marketing-local.sql).
-- * Custom domains: only stored as a pending request; the site_domain provider (Cloudflare for SaaS) is inactive.
-- Tables: RLS on, service_role only; versions/history/receipts immutable; functions security invoker.
begin;
create table if not exists public.pro_sites(
 owner_id uuid primary key references public.profiles(id) on delete cascade,
 slug text not null unique check(slug~'^[a-z0-9](?:[a-z0-9-]{1,46}[a-z0-9])$' and slug not in('baja','preview','admin','api','sitio')),
 theme text not null default 'contratacr' check(theme in('contratacr','cielo','noche','arena')),
 draft jsonb not null check(jsonb_typeof(draft)='object' and octet_length(draft::text)<=65536),
 custom_domain text check(custom_domain is null or custom_domain~'^([a-z0-9-]{1,63}\.)+[a-z]{2,24}$'),
 revision integer not null default 1 check(revision>0),
 published_version integer check(published_version is null or published_version>0),
 published_at timestamptz,
 created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),
 check((published_version is null)=(published_at is null))
);
create table if not exists public.pro_site_versions(
 owner_id uuid not null references public.pro_sites(owner_id) on delete cascade,
 version integer not null check(version>0),slug text not null,theme text not null,
 content jsonb not null check(jsonb_typeof(content)='object' and octet_length(content::text)<=65536),
 content_hash text not null check(content_hash~'^[a-f0-9]{64}$'),
 action_id uuid not null,published_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,version)
);
create table if not exists public.pro_site_actions(
 owner_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 input jsonb not null,result jsonb not null,created_at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id)
);
create table if not exists public.pro_site_history(
 owner_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 action text not null check(action in('save','publish','unpublish','domain')),revision integer not null,version integer,
 at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id)
);
create table if not exists public.pro_site_submissions(
 owner_id uuid not null references public.profiles(id) on delete cascade,submission_id uuid not null,
 version integer not null,input_hash text not null check(input_hash~'^[a-f0-9]{64}$'),
 lead_id uuid not null,client_id text not null,campaign_id uuid,marketing_consent boolean not null,
 result jsonb not null,created_at timestamptz not null default clock_timestamp(),primary key(owner_id,submission_id)
);
create or replace function public.pro_site_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Published versions, history and receipts are immutable' using errcode='23514';end $$;
do $$declare t text;begin foreach t in array array['pro_site_versions','pro_site_actions','pro_site_history','pro_site_submissions'] loop
 execute format('drop trigger if exists %I on public.%I',t||'_immutable',t);
 execute format('create trigger %I before update on public.%I for each row execute function public.pro_site_immutable()',t||'_immutable',t);
end loop;end $$;

-- ---------------------------------------------------------------- profile data the editor may reuse
-- plpgsql (not sql) so the body is resolved at call time: the offline PGlite check has no profile/review columns.
create or replace function public.pro_site_photos(p_owner uuid) returns text[]
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin return (
 with p as(select * from public.professionals where profile_id=p_owner),
 urls as(
  select unnest(coalesce(p.portfolio_urls,'{}')) u from p
  union all select i->>'url' from p,jsonb_array_elements(case when jsonb_typeof(p.portfolio_items)='array' then p.portfolio_items else '[]' end) i where jsonb_typeof(i)='object'
  union all select case when jsonb_typeof(ph)='string' then ph#>>'{}' else ph->>'url' end from p,jsonb_array_elements(case when jsonb_typeof(p.portfolio_items)='array' then p.portfolio_items else '[]' end) i,
   jsonb_array_elements(case when jsonb_typeof(i)='object' and jsonb_typeof(i->'photos')='array' then i->'photos' else '[]' end) ph
  union all select s->>'imageUrl' from p,jsonb_array_elements(case when jsonb_typeof(p.services)='array' then p.services else '[]' end) s where jsonb_typeof(s)='object')
 select coalesce(array_agg(distinct u) filter(where u~'^https://[^\s"<>]+$' and length(u) between 12 and 1000),'{}') from urls
);end $$;
create or replace function public.pro_site_profile(p_owner uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin return (
 select jsonb_build_object('businessName',coalesce(nullif(btrim(p.business_name),''),f.full_name),'profileSlug',p.slug,'bio',left(coalesce(p.bio,''),600),
  'services',coalesce((select jsonb_agg(jsonb_build_object('name',left(s->>'name',120),'description',left(coalesce(s->>'description',''),400))) from jsonb_array_elements(case when jsonb_typeof(p.services)='array' then p.services else '[]' end) s where jsonb_typeof(s)='object' and coalesce(btrim(s->>'name'),'')<>''),'[]'),
  'photos',to_jsonb(public.pro_site_photos(p_owner)),
  'area',jsonb_build_object('provincia',(select name from public.provincias where id=p.provincia_id),'canton',(select name from public.cantones where id=p.canton_id)),
  'rating',jsonb_build_object('average',p.rating_avg,'count',p.review_count))
 from public.profiles f left join public.professionals p on p.profile_id=f.id where f.id=p_owner
);end $$;
create or replace function public.pro_site_reviews(p_owner uuid,p_max integer) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin return (
 select coalesce(jsonb_agg(jsonb_build_object('rating',r.rating,'comment',left(r.comment,600),'name',r.who,'date',to_char(r.created_at at time zone 'America/Costa_Rica','YYYY-MM-DD')) order by r.created_at desc),'[]')
 from (select v.rating,v.comment,v.created_at,
   btrim(split_part(btrim(coalesce(nullif(v.client_name_snapshot,''),c.full_name,'Cliente')),' ',1)||coalesce(' '||nullif(left(split_part(btrim(coalesce(nullif(v.client_name_snapshot,''),c.full_name,'')),' ',2),1),'')||'.','')) who
  from public.reviews v join public.professionals p on p.id=v.professional_id left join public.profiles c on c.id=v.client_id
  where p.profile_id=p_owner and v.moderation_status='published' and length(btrim(v.comment))>0 order by v.created_at desc limit greatest(least(coalesce(p_max,6),12),0)) r
);end $$;

-- Draft shape checked here (the route validates every field with zod first).
create or replace function public.pro_site_content_ok(p_content jsonb) returns boolean
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
declare s jsonb;
begin
 if jsonb_typeof(p_content)<>'object' or jsonb_typeof(p_content->'sections')<>'array' or jsonb_array_length(p_content->'sections') not between 1 and 12
  or coalesce(length(p_content->>'title'),0) not between 1 and 70 or coalesce(length(p_content->>'description'),0) not between 1 and 170 then return false;end if;
 for s in select * from jsonb_array_elements(p_content->'sections') loop
  if jsonb_typeof(s)<>'object' or s->>'type' not in('hero','services','portfolio','reviews','area','contact') or jsonb_typeof(s->'enabled')<>'boolean' then return false;end if;
 end loop;
 return (select count(distinct x->>'type')=count(*) from jsonb_array_elements(p_content->'sections') x);
end $$;
create or replace function public.pro_site_section(p_content jsonb,p_type text) returns jsonb
language sql immutable security invoker set search_path=public,pg_temp as $$
 select x from jsonb_array_elements(p_content->'sections') x where x->>'type'=p_type and (x->>'enabled')::boolean limit 1 $$;
/** What a visitor (or the owner's preview) receives. Only names a visitor may see: no owner id, email or ids. */
create or replace function public.pro_site_resolve(p_owner uuid,p_slug text,p_theme text,p_content jsonb,p_version integer,p_published timestamptz) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('slug',p_slug,'theme',p_theme,'version',p_version,'publishedAt',p_published,'content',p_content,
  'business',(public.pro_site_profile(p_owner)->>'businessName'),'profileSlug',(public.pro_site_profile(p_owner)->>'profileSlug'),
  'rating',public.pro_site_profile(p_owner)->'rating',
  'reviews',case when public.pro_site_section(p_content,'reviews') is null then '[]'::jsonb else public.pro_site_reviews(p_owner,coalesce((public.pro_site_section(p_content,'reviews')->>'max')::int,6)) end,
  'campaigns',coalesce((select jsonb_agg(k.code) from public.pro_ad_campaigns k where k.owner_id=p_owner and not k.archived and k.landing='site'),'[]')) $$;

-- ---------------------------------------------------------------- owner read / mutate
create or replace function public.pro_site_read(p_actor uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare s public.pro_sites;
begin
 perform public.pro_mkt_owner(p_actor);
 select * into s from public.pro_sites where owner_id=p_actor;
 return jsonb_build_object('site',case when s.owner_id is null then null else jsonb_build_object('slug',s.slug,'theme',s.theme,'draft',s.draft,'customDomain',s.custom_domain,'revision',s.revision,'publishedVersion',s.published_version,'publishedAt',s.published_at,'updatedAt',s.updated_at,
   'draftChanged',s.published_version is null or s.draft is distinct from (select v.content from public.pro_site_versions v where v.owner_id=p_actor and v.version=s.published_version) or s.theme is distinct from (select v.theme from public.pro_site_versions v where v.owner_id=p_actor and v.version=s.published_version)) end,
  'versions',coalesce((select jsonb_agg(jsonb_build_object('version',v.version,'slug',v.slug,'theme',v.theme,'publishedAt',v.published_at,'contentHash',v.content_hash) order by v.version desc) from public.pro_site_versions v where v.owner_id=p_actor),'[]'),
  'profile',public.pro_site_profile(p_actor),
  'submissions',(select count(*) from public.pro_site_submissions where owner_id=p_actor),
  'preview',case when s.owner_id is null then null else public.pro_site_resolve(p_actor,s.slug,s.theme,s.draft,null,null) end);
end $$;
create or replace function public.pro_site_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text:=p_input->>'action';aid uuid;receipt public.pro_site_actions;s public.pro_sites;rev integer;ver integer;result jsonb;photo text;allowed text[];
begin
 perform public.pro_mkt_owner(p_actor);
 if jsonb_typeof(p_input)<>'object' or act not in('save','publish','unpublish','domain') or jsonb_typeof(p_input->'revision')<>'number' then raise exception 'Invalid site action' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;exception when others then raise exception 'Invalid action id' using errcode='22023';end;
 if aid is null then raise exception 'Missing action id' using errcode='22023';end if;
 rev:=(p_input->>'revision')::integer;
 perform pg_advisory_xact_lock(hashtextextended('pro-site:'||p_actor::text,0));
 select * into receipt from public.pro_site_actions where owner_id=p_actor and action_id=aid;
 if found then if receipt.input is distinct from p_input then raise exception 'Action id reused' using errcode='22023';end if;return receipt.result;end if;
 select * into s from public.pro_sites where owner_id=p_actor for update;
 if coalesce(s.revision,0)<>rev then raise exception 'Site changed' using errcode='40001';end if;
 if act='save' then
  if not public.pro_site_content_ok(p_input->'content') then raise exception 'Invalid site content' using errcode='22023';end if;
  if not found then insert into public.pro_sites(owner_id,slug,theme,draft) values(p_actor,p_input->>'slug',coalesce(p_input->>'theme','contratacr'),p_input->'content') returning * into s;
  else update public.pro_sites set slug=p_input->>'slug',theme=coalesce(p_input->>'theme','contratacr'),draft=p_input->'content',revision=revision+1,updated_at=clock_timestamp() where owner_id=p_actor returning * into s;end if;
 else
  if not found then raise exception 'Save the site first' using errcode='P0002';end if;
  if act='publish' then
   allowed:=public.pro_site_photos(p_actor);
   for photo in select jsonb_array_elements_text(coalesce(public.pro_site_section(s.draft,'portfolio')->'photos','[]')) loop
    if not photo=any(allowed) then raise exception 'Portfolio photos must come from your ContrataCR profile' using errcode='22023',hint='pro_site_foreign_photo';end if;
   end loop;
   ver:=coalesce((select max(version) from public.pro_site_versions where owner_id=p_actor),0)+1;
   insert into public.pro_site_versions(owner_id,version,slug,theme,content,content_hash,action_id) values(p_actor,ver,s.slug,s.theme,s.draft,encode(sha256(convert_to(s.draft::text,'UTF8')),'hex'),aid);
   update public.pro_sites set published_version=ver,published_at=clock_timestamp(),revision=revision+1,updated_at=clock_timestamp() where owner_id=p_actor returning * into s;
  elsif act='unpublish' then
   if s.published_version is null then raise exception 'Not published' using errcode='40001';end if;
   update public.pro_sites set published_version=null,published_at=null,revision=revision+1,updated_at=clock_timestamp() where owner_id=p_actor returning * into s;
  else
   update public.pro_sites set custom_domain=nullif(lower(btrim(coalesce(p_input->>'customDomain',''))),''),revision=revision+1,updated_at=clock_timestamp() where owner_id=p_actor returning * into s;
  end if;
 end if;
 insert into public.pro_site_history(owner_id,action_id,action,revision,version) values(p_actor,aid,act,s.revision,ver);
 result:=jsonb_build_object('action',act,'revision',s.revision,'slug',s.slug,'publishedVersion',s.published_version,'version',ver);
 insert into public.pro_site_actions(owner_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

-- ---------------------------------------------------------------- public (slug only)
create or replace function public.pro_site_public(p_slug text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare s public.pro_sites;v public.pro_site_versions;
begin
 select * into s from public.pro_sites where slug=p_slug and published_version is not null;
 if not found or not coalesce(public.pro_private_work_tools_enabled(s.owner_id),false) then return null;end if;
 select * into v from public.pro_site_versions where owner_id=s.owner_id and version=s.published_version;
 return public.pro_site_resolve(s.owner_id,v.slug,v.theme,v.content,v.version,v.published_at);
end $$;
create or replace function public.pro_site_published_slugs() returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce(jsonb_agg(jsonb_build_object('slug',s.slug,'publishedAt',s.published_at) order by s.slug),'[]') from public.pro_sites s where s.published_version is not null and coalesce(public.pro_private_work_tools_enabled(s.owner_id),false) $$;
create or replace function public.pro_site_visit(p_slug text,p_code text) returns boolean
language plpgsql security invoker set search_path=public,pg_temp as $$
declare s public.pro_sites;k public.pro_ad_campaigns;
begin
 select * into s from public.pro_sites where slug=p_slug and published_version is not null;if not found then return false;end if;
 select * into k from public.pro_ad_campaigns where owner_id=s.owner_id and code=p_code and not archived;if not found then return false;end if;
 insert into public.pro_ad_visits(owner_id,campaign_id,day,visits) values(s.owner_id,k.id,public.pro_ad_cr_day(now()),1)
 on conflict(owner_id,campaign_id,day) do update set visits=pro_ad_visits.visits+1;
 return true;
end $$;
-- The request form: customer + lead (lead center) + attribution + optional marketing consent, exactly once per submissionId.
create or replace function public.pro_site_submit(p_slug text,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare s public.pro_sites;v public.pro_site_versions;prior public.pro_site_submissions;sub uuid;h text;cid text;lid uuid:=gen_random_uuid();k public.pro_ad_campaigns;
 origin text;channel jsonb;crev integer;title text;answer jsonb;consent boolean;email text;name text;phone text;mail text;
begin
 if jsonb_typeof(p_input)<>'object' then raise exception 'Invalid request' using errcode='22023';end if;
 begin sub:=(p_input->>'submissionId')::uuid;exception when others then raise exception 'Invalid request' using errcode='22023';end;
 name:=btrim(coalesce(p_input->>'name',''));email:=lower(btrim(coalesce(p_input->>'email','')));phone:=btrim(coalesce(p_input->>'phone',''));consent:=coalesce((p_input->>'marketingConsent')::boolean,false);
 mail:=email;
 if sub is null or length(name) not between 2 and 120 or email!~'^[^@\s]+@[^@\s]+\.[^@\s]+$' or length(email)>254 or length(phone)>30 or length(coalesce(p_input->>'message','')) not between 5 and 2000
  or length(coalesce(p_input->>'service',''))>120 or (consent and coalesce(length(p_input->>'consentText'),0) not between 20 and 1000) then raise exception 'Invalid request' using errcode='22023';end if;
 select * into s from public.pro_sites where slug=p_slug and published_version is not null;
 if not found or not coalesce(public.pro_private_work_tools_enabled(s.owner_id),false) then raise exception 'Site unavailable' using errcode='P0002';end if;
 select * into v from public.pro_site_versions where owner_id=s.owner_id and version=s.published_version;
 if public.pro_site_section(v.content,'contact') is null then raise exception 'This site has no request form' using errcode='P0002';end if;
 -- confirmBase/language only shape the confirmation email; they are not part of the visitor's request identity.
 h:=encode(sha256(convert_to((p_input-'utm'-'confirmBase'-'language')::text,'UTF8')),'hex');
 perform pg_advisory_xact_lock(hashtextextended(s.owner_id::text,0));
 select * into prior from public.pro_site_submissions where owner_id=s.owner_id and submission_id=sub;
 if found then if prior.input_hash<>h then raise exception 'Submission id reused' using errcode='22023';end if;return prior.result;end if;
 -- Security review 2026-11-13: abuse caps of the public form, in the database (the route's per-IP limit trusts proxy
 -- headers and lives in memory). Per site owner: 200 requests a day; per e-mail address: 5 a day. 54000 → 429.
 if (select count(*) from public.pro_site_submissions ss where ss.owner_id=s.owner_id and ss.created_at>clock_timestamp()-interval '1 day')>=200
  or (select count(*) from public.pro_site_submissions ss join public.pro_clients pc on pc.user_id=ss.owner_id and pc.id=ss.client_id
      where ss.owner_id=s.owner_id and ss.created_at>clock_timestamp()-interval '1 day' and pc.email=mail)>=5 then
  raise exception 'Too many requests from this site form' using errcode='54000',hint='pro_site_submit_cap';end if;
 -- An address that unsubscribed may still send a request: it is accepted, but consent is NOT granted again (the
 -- answer is the same, so the form does not reveal who unsubscribed).
 if consent and exists(select 1 from public.pro_mkt_suppressions where owner_id=s.owner_id and email_hash=public.pro_mkt_email_hash(mail)) then consent:=false;end if;
 if p_input->>'code' is not null then select * into k from public.pro_ad_campaigns where owner_id=s.owner_id and code=p_input->>'code' and not archived;end if;
 -- customer (contact) of the owner
 cid:='sitio-'||sub::text;
 insert into public.pro_workspace_core(user_id,document,revision) values(s.owner_id,'{"version":1,"social":[]}',1) on conflict do nothing;
 insert into public.pro_clients(user_id,id,name,email,phone,notes,archived) values(s.owner_id,cid,name,email,phone,'Solicitud desde su sitio web',false);
 update public.pro_workspace_core set revision=revision+1,updated_at=now() where user_id=s.owner_id;
 -- lead in the existing lead center, with its origin channel
 origin:=public.pro_ad_channel_origin(k.channel);channel:=public.pro_lead_origin_channel_json(s.owner_id,origin);
 crev:=(public.pro_lead_origin_stage_catalog(s.owner_id)->>'revision')::integer;
 title:=left('Sitio web: '||coalesce(nullif(btrim(p_input->>'service'),''),name),160);
 perform public.pro_lead_origin_create(s.owner_id,jsonb_build_object('action','create_lead','actionId',public.pro_site_derived(sub,'origin'),
  'lead',jsonb_build_object('action','create','kind','manual','actionId',public.pro_site_derived(sub,'lead'),'id',lid,'revision',0,'catalogRevision',crev,'clientId',cid,'title',title,
   'description',left(btrim(p_input->>'message')||case when phone<>'' then E'\nTel.: '||phone else '' end||E'\nCorreo: '||email,2000),'address',left(coalesce(p_input->>'area',''),500),
   'sourceLabel',left('Sitio web'||coalesce(' · '||k.name,''),80),'forecast',jsonb_build_object('projectType',left(coalesce(p_input->>'service',''),80),'expectedStart',null,'currency','CRC','revenueCents',null,'budgetCents',null,'profitCents',null),'stageMode','automatic','stageId',null),
  'channel',case when channel is null or coalesce((channel->>'archived')::boolean,false) then 'null'::jsonb else jsonb_build_object('id',origin,'revision',(channel->>'revision')::integer) end));
 insert into public.pro_lead_attributions(owner_id,lead_id,campaign_id,source,utm) values(s.owner_id,lid,k.id,'site_form',
  coalesce((select jsonb_object_agg(key,left(value#>>'{}',80)) from jsonb_each(case when jsonb_typeof(p_input->'utm')='object' then p_input->'utm' else '{}' end) where key in('source','medium','campaign','content','term') and jsonb_typeof(value)='string'),'{}'));
 -- Post-security fixes (Ley 8968, double opt-in): the tick only creates a PENDING contact and a confirmation email
 -- (mock: never sent); consent exists only after the recipient confirms from that email (pro_mkt_confirm).
 if consent then perform public.pro_mkt_request_confirmation(s.owner_id,email,name,p_input->>'consentText',jsonb_build_object('submissionId',sub,'siteVersion',v.version,'slug',s.slug),cid,lid,
  p_input->>'confirmBase',case when p_input->>'language'='en' then 'en' else 'es' end);end if;
 answer:=jsonb_build_object('ok',true,'business',public.pro_mkt_business(s.owner_id));
 insert into public.pro_site_submissions(owner_id,submission_id,version,input_hash,lead_id,client_id,campaign_id,marketing_consent,result) values(s.owner_id,sub,v.version,h,lid,cid,k.id,consent,answer);
 return answer;
end $$;
create or replace function public.pro_site_derived(p_base uuid,p_label text) returns uuid
language sql immutable security invoker set search_path=public,pg_temp as $$
 select (substr(h,1,8)||'-'||substr(h,9,4)||'-4'||substr(h,14,3)||'-'||'8'||substr(h,18,3)||'-'||substr(h,21,12))::uuid from (select md5('ccr-site:'||p_base::text||':'||p_label) h) x $$;

do $$declare n text;begin foreach n in array array['pro_sites','pro_site_versions','pro_site_actions','pro_site_history','pro_site_submissions'] loop
 execute format('alter table public.%I enable row level security',n);execute format('revoke all on public.%I from public,anon,authenticated,service_role',n);execute format('grant select,insert,update on public.%I to service_role',n);
end loop;end $$;
do $$declare f regprocedure;begin
 for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'pro\_site\_%' loop
  execute format('revoke all on function %s from public,anon,authenticated',f);
  if f::text not like 'pro_site_immutable(%' then execute format('grant execute on function %s to service_role',f);end if;
 end loop;end $$;
notify pgrst,'reload schema';
commit;
